SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 259) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 259 END, 'db_describe', 'DB describe (any database)', 'Describe ANY database: without `table` it lists tables/views with row estimates; with `table` it returns columns + types + nullability + defaults, indexes and constraints, and the exact row count. Use it before writing SQL, and after a db_execute that changed a table.', 'python_function', 'custom', '{"function_name": "db_describe", "code": "# --- imports ---\ndef db_describe(db_name: str = \"\", table: str = \"\", ontology_key: str = \"\") -> str:\n    \"\"\"Tables of any database (with row estimates), or one table''s columns — and with NO database name,\n    the server''s databases (this absorbed `db_list_databases`: enumerating databases and describing one\n    were two doors onto the same discovery question).\"\"\"\n    from services import db_admin\n\n    if not (db_name or \"\").strip():\n        try:\n            out = db_admin.list_databases(with_objects=False, ontology_key=ontology_key)\n        except db_admin.DbAdminError as exc:\n            return f\"REFUSED: {exc}\"\n        except Exception as exc:                                # noqa: BLE001\n            return f\"ERROR: {type(exc).__name__}: {exc}\"\n        lines = [f\"{out[''count'']} database(s) on this server:\", \"\"]\n        for d in out[\"databases\"]:\n            lines.append(f\"- {d[''database'']:<32} {d[''size'']:>8}  owner={d[''owner'']}\"\n                         + (\"\" if d.get(\"writable\", True) else \"  [read-only]\"))\n        lines += [\"\", \"next: db_describe(db_name=...) for one database''s tables.\"]\n        return \"\\n\".join(lines)\n\n    try:\n        out = db_admin.describe(db_name, table, ontology_key=ontology_key)\n    except db_admin.DbAdminError as exc:\n        return f\"REFUSED: {exc}\"\n    except Exception as exc:                                    # noqa: BLE001\n        return f\"ERROR: {type(exc).__name__}: {exc}\"\n    if not table:\n        lines = [f\"{out[''database'']}: {out[''count'']} table(s)/view(s)\", \"\"]\n        for t in out[\"tables\"]:\n            lines.append(f\"- {t[''schema'']}.{t[''table'']:<32} {t[''kind'']:<11} \"\n                         f\"rows~{t[''rows_estimate'']:<8} {t[''size'']}\")\n        return \"\\n\".join(lines)\n    lines = [f\"{out[''database'']}.{out[''table'']}  ({out[''rows'']} rows)\", \"\", \"columns:\"]\n    for c in out[\"columns\"]:\n        null = \"NULL\" if c[\"nullable\"] else \"NOT NULL\"\n        dflt = f\" default={c[''default'']}\" if c[\"default\"] else \"\"\n        lines.append(f\"- {c[''column'']:<24} {c[''type'']:<18} {null}{dflt}\")\n    if out[\"indexes\"]:\n        lines += [\"\", \"indexes:\"] + [f\"- {i[''index'']}: {i[''definition'']}\" for i in out[\"indexes\"]]\n    if out[\"constraints\"]:\n        lines += [\"\", \"constraints:\"] + [f\"- {c[''constraint'']} ({c[''kind'']}): {c[''definition'']}\"\n                                          for c in out[\"constraints\"]]\n    return \"\\n\".join(lines)\n", "args_schema": {"db_name": {"type": "string", "description": "database to describe; EMPTY lists the databases on this server (this absorbed the old db_list_databases)", "default": ""}, "table": {"type": "string", "description": "one table (empty = list them all)", "default": ""}}}', '{"type": "object", "properties": {"db_name": {"type": "string", "description": "database to describe; EMPTY lists the databases on this server (this absorbed the old db_list_databases)", "default": ""}, "table": {"type": "string", "description": "one table (empty = list them all)", "default": ""}}, "required": []}', 'string', NULL, '{"category": "database", "order": 2, "section": null, "is_concurrency_safe": false, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, NULL, FALSE, NULL, 13, '2026-11-25 16:41:55.929233+00:00', 1, '2026-11-25 08:42:33.852540+00:00', '1.0.0', NULL, 'database', TRUE, 'false', '["database", "admin", "postgres", "ddl"]', '2026-11-25 08:30:45.259228+00:00', '2026-11-25 16:58:56.543169+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'db_describe');

