SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 260) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 260 END, 'db_execute', 'DB execute (one write statement)', '【写别的库就用我】Run ONE write statement against a named database: INSERT/UPDATE/DELETE and DDL (CREATE/ALTER/DROP/TRUNCATE/COMMENT). TWO PHASES — confirm=false returns the plan and executes nothing; only confirm=true runs it. Refuses, by name: stacked statements, server-level verbs (DROP DATABASE, DROP SCHEMA, ALTER SYSTEM, roles, grants), the platform''s own database, and template0/template1/postgres. NOT limited to business databases: row-level DML on the platform is allowed here too (this tool refuses the platform database by its db_name argument); NOT for reading — `db_query` / `db_describe`.', 'python_function', 'custom', '{"function_name": "db_execute", "code": "# --- imports ---\ndef db_execute(db_name: str, sql: str, confirm: bool = False) -> str:\n    \"\"\"Run ONE write statement (DDL/DML) against a named database. Two phases: plan, then confirm.\n\n    The platform''s own database is accepted for ROW-LEVEL DML only (INSERT/UPDATE/DELETE); DDL on it is\n    refused — that one belongs in psql as an administrator. This is the ONLY write tool: it absorbed\n    the old `pg_execute`, which was deleted (see db-tools-review.md §B).\n    \"\"\"\n    from services import db_admin\n\n    try:\n        out = db_admin.execute(db_name, sql, confirm=confirm)\n    except db_admin.DbAdminError as exc:\n        return f\"REFUSED: {exc}\"\n    except Exception as exc:                                    # noqa: BLE001\n        return f\"ERROR: {type(exc).__name__}: {exc}\"\n    if not out.get(\"executed\"):\n        return (\"NOTHING WAS EXECUTED (confirm=false).\\n\"\n                f\"database: {out[''database'']}\\nkind: {out[''kind'']}\\nstatement:\\n  {out[''statement'']}\\n\\n\"\n                + str(out.get(\"next\") or \"\"))\n    affected = out.get(\"rows_affected\")\n    return (f\"executed against {out[''database'']}  ({out[''kind'']})\\n\"\n            f\"  {out[''statement'']}\\n\"\n            f\"  rows_affected={affected}  ({out.get(''note'', '''')})\")\n", "args_schema": {"db_name": {"type": "string", "description": "database the statement runs against"}, "sql": {"type": "string", "description": "ONE statement; a trailing '';'' is fine"}, "confirm": {"type": "boolean", "description": "false (default) = plan only; true = execute it", "default": false}}}', '{"type": "object", "properties": {"db_name": {"type": "string", "description": "database the statement runs against"}, "sql": {"type": "string", "description": "ONE statement; a trailing '';'' is fine"}, "confirm": {"type": "boolean", "description": "false (default) = plan only; true = execute it", "default": false}}, "required": ["db_name", "sql"]}', 'string', NULL, '{"category": "database", "order": 2, "section": null, "is_concurrency_safe": false, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, NULL, FALSE, NULL, 3, '2026-11-25 11:49:49.764700+00:00', 0, NULL, '1.0.0', NULL, 'database', TRUE, 'false', '["database", "admin", "postgres", "ddl"]', '2026-11-25 08:30:45.259228+00:00', '2026-11-25 16:58:56.543169+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'db_execute');

