SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 53) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 53 END, 'doc_index_list', 'Doc Index - List Documents', 'List all indexed documents with metadata. Uses vectorless RAG (no embeddings, no chunking). Returns document names, types, and page counts.', 'python_function', 'custom', '{"function_name": "doc_index_list", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nimport os\n\n_DOC_INDEX_BASE = None\n\ndef _get_doc_index_base() -> str:\n    \"\"\"Get the doc_index workspace base path.\"\"\"\n    global _DOC_INDEX_BASE\n    if _DOC_INDEX_BASE is None:\n        try:\n            # Follow the env-configurable workspace root (WORKSPACE_BASE_DIR).\n            from services.workspace_manager import get_workspace_manager\n            default_base = str(get_workspace_manager().base_dir / \"default\")\n        except Exception:\n            default_base = os.path.join(\n                os.path.dirname(os.path.dirname(__file__)), \"outputs\", \"default\"\n            )\n        _DOC_INDEX_BASE = os.environ.get(\"DOC_INDEX_BASE\", default_base)\n    return _DOC_INDEX_BASE\n\ndef _get_doc_client():\n    \"\"\"Get a DocIndexClient for the current workspace.\"\"\"\n    from services.doc_index_service import DocIndexClient\n    return DocIndexClient(_get_doc_index_base())\n\ndef doc_index_list(workspace: Optional[str] = None) -> str:\n    \"\"\"\n    用我：列出某项目里可做页级检索的文档。\n    别用我：本账号上传文档用 rag_search。\n\n    List all indexed documents with metadata.\n\n    Uses GraphIndex-style vectorless retrieval — no embeddings, no chunking.\n    Returns document names, types, and page counts.\n\n    Args:\n        workspace: Optional override for the doc_index workspace path\n    \"\"\"\n    try:\n        if workspace:\n            from services.doc_index_service import DocIndexClient\n            client = DocIndexClient(workspace)\n        else:\n            client = _get_doc_client()\n\n        docs = client.list_all()\n        if not docs:\n            return \"No documents indexed yet.\"\n\n        lines = [\"## Indexed Documents\", \"\"]\n        for doc_id, meta in docs.items():\n            lines.append(f\"- **{meta.get(''doc_name'', ''Unknown'')}** ({meta.get(''type'', ''?'')})\")\n            lines.append(f\"  ID: `{doc_id}`\")\n            lines.append(f\"  Pages: {meta.get(''page_count'', 0)}\")\n            lines.append(\"\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"Error listing documents: {e}\"", "args_schema": {"workspace": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"workspace": {"type": "string", "description": "", "default": null}}, "required": []}', 'string', NULL, '{"category": "graph", "order": 39, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034579+00:00', '2026-11-25 17:22:15.346181+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'doc_index_list');

