SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 104) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 104 END, 'gen_html_deck', 'Generate HTML Deck', '用我：把 slides_json 渲染成单文件 HTML 幻灯片。
    别用我：普通网页/文档用 write_file。
Generate a single-file themed HTML slide deck from a slides JSON outline.

    Args:
        title: Deck title (used in the HTML <title> and fallback filename).
        slides_json: JSON object with "title" and "slides" (same schema as
            gen_pptx: types title|section|content|data|conclusion|closing|image,
            optional bullets / highlight / speaker_notes).
        output_dir: Optional directory (inside the presentation output folder).
        theme: Named template palette (business|fashion|tech|health|education|minimal).
        filename: Optional explicit filename (must end .html).

    Returns:
        Absolute path to the generated .html file.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import gen_html_deck\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"用我：把 slides_json 渲染成单文件 HTML 幻灯片。     别用我：普通网页/文档用 write_file。 Generate a single-file themed HTML slide deck from a slides JSON outline.      Args:         titl\"\"\"\n    return str(await gen_html_deck.ainvoke({**kwargs}))\n", "args_schema": {"title": {"type": "string", "description": ""}, "slides_json": {"type": "string", "description": ""}, "output_dir": {"type": "string", "description": "", "default": ""}, "theme": {"type": "string", "description": "", "default": "business"}, "filename": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"title": {"type": "string", "description": ""}, "slides_json": {"type": "string", "description": ""}, "output_dir": {"type": "string", "description": "", "default": ""}, "theme": {"type": "string", "description": "", "default": "business"}, "filename": {"type": "string", "description": "", "default": ""}}, "required": ["title", "slides_json"]}', 'string', NULL, '{"category": "presentation", "order": 21, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-25 14:20:15.078089+00:00', '2026-11-25 17:22:15.346202+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'gen_html_deck');

