SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 105) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 105 END, 'gen_pdf_deck', 'Generate PDF Deck', '用我：把 slides_json 渲染成 PDF 幻灯片。
    别用我：普通文档转 PDF 用 write_file（按扩展名）。
Generate a themed PDF slide deck (one landscape page per slide) via fpdf.

    Args:
        title: Deck title (used in the fallback filename).
        slides_json: JSON object with "title" and "slides" (same schema as
            gen_pptx). CJK text is supported via a Unicode font.
        output_dir: Optional directory (inside the presentation output folder).
        theme: Named template palette (business|fashion|tech|health|education|minimal).
        filename: Optional explicit filename (must end .pdf).

    Returns:
        Absolute path to the generated .pdf file.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import gen_pdf_deck\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"用我：把 slides_json 渲染成 PDF 幻灯片。     别用我：普通文档转 PDF 用 write_file（按扩展名）。 Generate a themed PDF slide deck (one landscape page per slide) via fpdf.      Args:        \"\"\"\n    return str(await gen_pdf_deck.ainvoke({**kwargs}))\n", "args_schema": {"title": {"type": "string", "description": ""}, "slides_json": {"type": "string", "description": ""}, "output_dir": {"type": "string", "description": "", "default": ""}, "theme": {"type": "string", "description": "", "default": "business"}, "filename": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"title": {"type": "string", "description": ""}, "slides_json": {"type": "string", "description": ""}, "output_dir": {"type": "string", "description": "", "default": ""}, "theme": {"type": "string", "description": "", "default": "business"}, "filename": {"type": "string", "description": "", "default": ""}}, "required": ["title", "slides_json"]}', 'string', NULL, '{"category": "presentation", "order": 22, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-25 14:20:15.078094+00:00', '2026-11-25 17:22:15.346202+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'gen_pdf_deck');

