SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 49) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 49 END, 'glob', 'Glob', 'Find files matching a glob pattern.

Supports patterns like "**/*.py" (all Python files) or "src/*.ts" (TypeScript in src).

Args:
    pattern: Glob pattern to match (e.g., "**/*.py", "*.md", "src/**/*.tsx")
    path: Base directory to search from (default: current directory)

Returns:
    List of matching file paths

Example:
    >>> glob("**/*.py")
    >>> glob("*.md", path="/docs")
    >>> glob("src/**/*.tsx")', 'python_function', 'custom', '{"function_name": "glob", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\nimport subprocess as _subprocess\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef glob(pattern: str, path: str = \".\") -> str:\n    \"\"\"\n    Find files matching a glob pattern.\n\n    Supports patterns like \"**/*.py\" (all Python files) or \"src/*.ts\" (TypeScript in src).\n\n    Args:\n        pattern: Glob pattern to match (e.g., \"**/*.py\", \"*.md\", \"src/**/*.tsx\")\n        path: Base directory to search from (default: current directory)\n\n    Returns:\n        List of matching file paths\n\n    Example:\n        >>> glob(\"**/*.py\")\n        >>> glob(\"*.md\", path=\"/docs\")\n        >>> glob(\"src/**/*.tsx\")\n    \"\"\"\n    try:\n        base_path, err = _resolve_sandbox_path(path)\n        if err:\n            return err\n\n        if not base_path.exists():\n            return f\"Error: Path not found: {path}\"\n\n        # ripgrep fast path when available (rg is much faster on large trees).\n        import shutil as _shutil\n        import subprocess as _subprocess\n        if _shutil.which(\"rg\") is not None and base_path.is_dir():\n            try:\n                proc = _subprocess.run(\n                    [\"rg\", \"--files\", \"-g\", pattern, \".\"],\n                    cwd=str(base_path), capture_output=True, text=True, timeout=30,\n                )\n                out = (proc.stdout or \"\").strip()\n                if out:\n                    return \"\\n\".join(out.splitlines()[:200])\n            except Exception:\n                pass  # fall back to the Python implementation\n\n        matches = list(base_path.glob(pattern))\n\n        if not matches:\n            return f\"No files found matching pattern ''{pattern}'' in {path}\"\n\n        # Format results with relative paths\n        result_lines = []\n        for match in sorted(matches):\n            try:\n                rel_path = match.relative_to(base_path)\n                result_lines.append(str(rel_path))\n            except ValueError:\n                result_lines.append(str(match))\n\n        logger.info(f\"Glob ''{pattern}'' found {len(matches)} files\")\n        return \"\\n\".join(result_lines)\n\n    except Exception as e:\n        logger.error(f\"Error with glob pattern {pattern}: {e}\")\n        return f\"Error searching for files: {str(e)}\"", "args_schema": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}}}', '{"type": "object", "properties": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}}, "required": ["pattern"]}', 'string', NULL, '{"category": "filesystem", "order": 7, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 13, '2026-11-25 17:44:04.145903+00:00', 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034571+00:00', '2026-11-11 02:00:59.919393+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'glob');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 95) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 95 END, 'graphindex_ingest', 'GraphIndex - Ingest File', 'Ingest a file into the graphindex: hash → dedup → enrich → upsert.', 'python_function', 'custom', '{"function_name": "graphindex_ingest", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nfrom contextvars import ContextVar\n\nimport os\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\n_GRAPHINDEX_PROJECT_ID: ContextVar = ContextVar(\"_GRAPHINDEX_PROJECT_ID\", default=None)\n\ndef _get_project_id() -> Optional[int]:\n    \"\"\"Get the current project ID from the request-scoped var (set during agent execution).\"\"\"\n    pid = _GRAPHINDEX_PROJECT_ID.get()\n    if pid is not None:\n        return pid\n    pid = os.environ.get(\"GRAPHINDEX_PROJECT_ID\")\n    if pid:\n        try:\n            return int(pid)\n        except (ValueError, TypeError):\n            return None\n    return None\n\ndef _run_capturing_stdout(fn, *args, **kwargs):\n    \"\"\"Run a function and capture its stdout.\n\n    Some cmd_* functions print reports to stdout. We redirect stdout\n    into a buffer so the result shows in the agent''s tool output.\n    \"\"\"\n    import io\n    import contextlib\n    buf = io.StringIO()\n    with contextlib.redirect_stdout(buf):\n        rc = fn(*args, **kwargs)\n    return rc, buf.getvalue().rstrip()\n\ndef _make_neo4j_index():\n    \"\"\"Create a Neo4jDocumentIndex from env vars.\"\"\"\n    from learning.phase9.graphindex.index_build import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef graphindex_ingest(file_path: str, project_id: Optional[int] = None,\n                      target_dir: Optional[str] = None) -> str:\n    \"\"\"Ingest a file into the graphindex: hash → dedup → enrich → upsert.\n\n    Uses ``learning.phase9.graphindex.index_build.cmd_ingest``.\n\n    Args:\n        file_path: Absolute path to the file on disk.\n        project_id: Optional project ID.\n        target_dir: Optional override for the target directory.\n    \"\"\"\n    # Request-scoped override (set by the chat route) takes precedence over the\n    # LLM-provided arg.\n    pid_override = _GRAPHINDEX_PROJECT_ID.get()\n    if pid_override is not None:\n        project_id = pid_override\n    elif not project_id:\n        project_id = _get_project_id()\n    if not project_id:\n        return (\"ERROR: no project_id provided.\")\n\n    try:\n        from learning.phase9.graphindex.index_build import cmd_ingest, make_llm\n        idx = _make_neo4j_index()\n        llm = make_llm()\n        rc, captured = _run_capturing_stdout(cmd_ingest, idx, llm, file_path,\n                                              target_dir=target_dir, project_id=project_id)\n        return captured or f\"## Ingest: {file_path}\\nreturn code: {rc}\"\n    except Exception as e:\n        return f\"❌ Error ingesting {file_path}: {e}\"", "args_schema": {"file_path": {"type": "string", "description": ""}, "project_id": {"type": "string", "description": ""}, "target_dir": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": ""}, "project_id": {"type": "string", "description": ""}, "target_dir": {"type": "string", "description": ""}}, "required": ["file_path"]}', 'string', NULL, '{"category": "graph", "order": 46, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-15 09:27:26.490193+00:00', '2026-11-25 17:22:15.346199+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'graphindex_ingest');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 58) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 58 END, 'graphindex_list_docs', 'GraphIndex - List Documents', 'List all documents in the project with their about-preview. Use this to discover what docs exist before calling graphindex_search.', 'python_function', 'custom', '{"function_name": "graphindex_list_docs", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nfrom contextvars import ContextVar\n\nimport os\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\n_GRAPHINDEX_DOC_SCOPE: ContextVar = ContextVar(\"_GRAPHINDEX_DOC_SCOPE\", default=None)\n\n_GRAPHINDEX_PROJECT_ID: ContextVar = ContextVar(\"_GRAPHINDEX_PROJECT_ID\", default=None)\n\ndef _get_project_id() -> Optional[int]:\n    \"\"\"Get the current project ID from the request-scoped var (set during agent execution).\"\"\"\n    pid = _GRAPHINDEX_PROJECT_ID.get()\n    if pid is not None:\n        return pid\n    pid = os.environ.get(\"GRAPHINDEX_PROJECT_ID\")\n    if pid:\n        try:\n            return int(pid)\n        except (ValueError, TypeError):\n            return None\n    return None\n\ndef _list_docs_from_pg(project_id: int) -> list:\n    \"\"\"Query ContextDocument from PostgreSQL as a fallback catalog.\n\n    Returns list of dicts with keys: name, about, id, file_path, filename.\n    \"\"\"\n    try:\n        from db.database import SessionLocal\n        from models.core import ContextDocument\n\n        db = SessionLocal()\n        try:\n            docs = db.query(ContextDocument).filter(\n                ContextDocument.project_id == project_id,\n            ).all()\n            return [\n                {\n                    \"name\": d.filename or f\"doc_{d.id}\",\n                    \"about\": d.description or \"(no description yet — indexing in progress)\",\n                    \"id\": d.id,\n                    \"file_path\": d.file_path or \"\",\n                    \"filename\": d.filename or f\"doc_{d.id}\",\n                }\n                for d in docs\n            ]\n        finally:\n            db.close()\n    except Exception:\n        return []\n\ndef graphindex_list_docs(project_id: Optional[int] = None) -> str:\n    \"\"\"List all documents available in the project.\n\n    First tries Neo4j (``learning.phase9.graphindex.route.fetch_catalog``).\n    If empty (indexing still in progress), falls back to PostgreSQL\n    ContextDocument table.\n\n    Args:\n        project_id: Optional project ID. If not provided, uses the\n            current project (from GRAPHINDEX_PROJECT_ID env var).\n            Returns an error if neither is set.\n    \"\"\"\n    # Request-scoped override (set by the chat route) takes precedence over the\n    # LLM-provided arg.\n    pid_override = _GRAPHINDEX_PROJECT_ID.get()\n    if pid_override is not None:\n        project_id = pid_override\n    elif not project_id:\n        project_id = _get_project_id()\n    if not project_id:\n        return (\"ERROR: no project_id provided. Either pass project_id \"\n                \"explicitly or set the GRAPHINDEX_PROJECT_ID env var.\")\n\n    try:\n        from learning.phase9.graphindex.route import fetch_catalog  # noqa: E402\n        from learning.phase9.graphindex.index_build import Neo4jDocumentIndex  # noqa: E402\n\n        idx = Neo4jDocumentIndex(\n            base_url=NEO4J_HTTP_URL,\n            username=NEO4J_HTTP_USER,\n            password=NEO4J_HTTP_PASSWORD,\n        )\n        idx.ensure_constraints()\n        rows = fetch_catalog(idx, project_id, doc_scope=_GRAPHINDEX_DOC_SCOPE.get() or \"all\")\n\n        if not rows:\n            # Fallback: PostgreSQL ContextDocuments (not yet Neo4j-indexed)\n            pg_docs = _list_docs_from_pg(project_id)\n            if not pg_docs:\n                return f\"No documents in project {project_id}.\"\n            rows = pg_docs\n\n        lines = [f\"## Documents in project {project_id} ({len(rows)} total)\", \"\"]\n        for i, r in enumerate(rows, 1):\n            about = (r.get(\"about\") or r.get(\"description\") or \"(no enrichment)\")[:80]\n            lines.append(f\"**[{i}] {r[''name'']}**\")\n            lines.append(f\"   {about}…\")\n            lines.append(\"\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing docs: {e}\"", "args_schema": {"project_id": {"type": "integer", "description": "", "default": null}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": "", "default": null}}, "required": []}', 'string', NULL, '{"category": "graph", "order": 44, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034588+00:00', '2026-11-25 17:22:15.346192+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'graphindex_list_docs');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 57) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 57 END, 'graphindex_load', 'GraphIndex - Load Document Content', 'Load the full content of a document by its context_doc_id (obtained from graphindex_search). Returns the complete document text for the agent to read. Respects scope — refuses to load docs outside the current chat scope.', 'python_function', 'custom', '{"function_name": "graphindex_load", "code": "# --- imports ---\n\nfrom contextvars import ContextVar\n\n_GRAPHINDEX_DOC_SCOPE: ContextVar = ContextVar(\"_GRAPHINDEX_DOC_SCOPE\", default=None)\n\ndef graphindex_load(context_doc_id: int, max_chars: int = 10_000_000) -> str:\n    \"\"\"\n    用我：按 graphindex_search 给的 context_doc_id 取回文档正文。\n    别用我：普通文件用 read_file。\nLoad the full content of a document by its context_doc_id.\n\n    Uses the canonical Phase 9 graphindex modules:\n      1. Lookup ContextDocument from DB by context_doc_id\n      2. Read full text via route._read_doc_text\n\n    Args:\n        context_doc_id: The document''s context_doc_id (from graphindex_search results).\n        max_chars: Hard cap on returned characters (default 10M = no cap).\n    \"\"\"\n    try:\n        from db.database import SessionLocal\n        from models.core import ContextDocument\n\n        db = SessionLocal()\n        try:\n            context_doc = db.query(ContextDocument).filter(\n                ContextDocument.id == context_doc_id\n            ).first()\n        finally:\n            db.close()\n\n        if not context_doc:\n            return f\"❌ Document with context_doc_id={context_doc_id} not found in either Postgres or Neo4j.\"\n\n        # Deterministic scope enforcement — refuse to load docs outside scope.\n        doc_scope = _GRAPHINDEX_DOC_SCOPE.get()\n        if doc_scope is not None:\n            if context_doc.filename not in doc_scope:\n                return (f\"SCOPE_ERROR: Document ''{context_doc.filename}'' is not in the \"\n                        f\"current chat scope. Only the following docs are visible to \"\n                        f\"this chat: {'', ''.join(doc_scope)}. \"\n                        f\"Search again within the selected scope, or ask the user to \"\n                        f\"clear the scope filter.\")\n\n        from learning.phase9.graphindex.index_build import load_document_content  # noqa: E402\n        full_content = load_document_content(context_doc.file_path or \"\")\n        if not full_content:\n            return (f\"❌ Could not extract text from {context_doc.filename} \"\n                    f\"(file_path={context_doc.file_path})\")\n\n        # Honor the caller''s character budget — the full doc is no longer dumped\n        # unconditionally (previously max_chars was a dead parameter).\n        if len(full_content) > max_chars:\n            full_content = full_content[:max_chars] + (\n                f\"\\n\\n[...truncated at {max_chars} chars — original length \"\n                f\"{len(full_content):,}...]\")\n\n        return (f\"## Document: {context_doc.filename}\\n\"\n                f\"Source: GraphIndex (Phase 9 read path)\\n\"\n                f\"Pages: {full_content.count(''--- Page '')}\\n\"\n                f\"Total characters: {len(full_content):,}\\n\\n\"\n                f\"--- Document Content ---\\n\"\n                f\"{full_content}\\n--- End of Document ---\\n\")\n    except Exception as e:\n        return f\"❌ Error loading document {context_doc_id}: {e}\"", "args_schema": {"context_doc_id": {"type": "integer", "description": ""}, "max_chars": {"type": "integer", "description": "", "default": 10000000}}}', '{"type": "object", "properties": {"context_doc_id": {"type": "integer", "description": ""}, "max_chars": {"type": "integer", "description": "", "default": 10000000}}, "required": ["context_doc_id"]}', 'string', NULL, '{"category": "graph", "order": 43, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034587+00:00', '2026-11-25 17:22:15.346191+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'graphindex_load');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 59) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 59 END, 'graphindex_multi_doc_load', 'GraphIndex - Multi-Doc Load', 'One-shot: route a query to the best primary document, then load primary + 0-3 supporting documents as a combined context string. Equivalent to calling graphindex_search + multiple graphindex_load in one step.', 'python_function', 'custom', '{"function_name": "graphindex_multi_doc_load", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nfrom contextvars import ContextVar\n\nimport os\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\n_GRAPHINDEX_DOC_SCOPE: ContextVar = ContextVar(\"_GRAPHINDEX_DOC_SCOPE\", default=None)\n\n_GRAPHINDEX_PROJECT_ID: ContextVar = ContextVar(\"_GRAPHINDEX_PROJECT_ID\", default=None)\n\ndef _get_project_id() -> Optional[int]:\n    \"\"\"Get the current project ID from the request-scoped var (set during agent execution).\"\"\"\n    pid = _GRAPHINDEX_PROJECT_ID.get()\n    if pid is not None:\n        return pid\n    pid = os.environ.get(\"GRAPHINDEX_PROJECT_ID\")\n    if pid:\n        try:\n            return int(pid)\n        except (ValueError, TypeError):\n            return None\n    return None\n\ndef graphindex_multi_doc_load(query: str, project_id: Optional[int] = None) -> str:\n    \"\"\"One-shot: route a query to the best document, then load its full text.\n\n    Uses GraphIndex vector matching (find_best_document) + load_doc_context.\n\n    The LLM is expected to call this tool with a fresh query for each\n    user turn. If the loaded doc''s content doesn''t actually answer the\n    question, the LLM should call `graphindex_search` again to re-route\n    to a different in-scope document before answering.\n\n    Args:\n        query: Natural language query (e.g., \"compare Nike strategy with industry trends\")\n        project_id: Optional project ID. Uses GRAPHINDEX_PROJECT_ID env var if not set.\n    \"\"\"\n    # Request-scoped override (set by the chat route) takes precedence over the\n    # LLM-provided arg.\n    pid_override = _GRAPHINDEX_PROJECT_ID.get()\n    if pid_override is not None:\n        project_id = pid_override\n    elif not project_id:\n        project_id = _get_project_id()\n    if not project_id:\n        return (\"ERROR: no project_id provided. Either pass project_id \"\n                \"explicitly or set the GRAPHINDEX_PROJECT_ID env var.\")\n\n    try:\n        from learning.phase9.graphindex.index_build import load_doc_context  # noqa: E402\n        from learning.phase9.graphindex.index_build import Neo4jDocumentIndex  # noqa: E402\n\n        idx = Neo4jDocumentIndex(\n            base_url=NEO4J_HTTP_URL,\n            username=NEO4J_HTTP_USER,\n            password=NEO4J_HTTP_PASSWORD,\n        )\n        idx.ensure_constraints()\n        docs = idx.list_documents(project_id=project_id)\n        if not docs:\n            return f\"No documents in project {project_id}.\"\n\n        best = idx.find_best_document(\n            project_id=project_id,\n            query=query,\n            scope=_GRAPHINDEX_DOC_SCOPE.get(),\n        )\n        if best is None:\n            return f\"No document matched ''{query}''.\"\n\n        context = load_doc_context(idx, project_id, [best.name])\n        header = (\n            f\"## Multi-doc context for: ''{query}''\\n\"\n            f\"primary: {best.name}\\n\"\n        )\n        return header + context\n    except Exception as e:\n        return f\"❌ Error in multi-doc load: {e}\"", "args_schema": {"query": {"type": "string", "description": ""}, "project_id": {"type": "integer", "description": "", "default": null}}}', '{"type": "object", "properties": {"query": {"type": "string", "description": ""}, "project_id": {"type": "integer", "description": "", "default": null}}, "required": ["query"]}', 'string', NULL, '{"category": "graph", "order": 45, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034590+00:00', '2026-11-25 17:22:15.346192+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'graphindex_multi_doc_load');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 96) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 96 END, 'graphindex_rebuild_one', 'GraphIndex - Rebuild One Document', 'Re-enrich ONE existing document in the graphindex.', 'python_function', 'custom', '{"function_name": "graphindex_rebuild_one", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nfrom contextvars import ContextVar\n\nimport os\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\n_GRAPHINDEX_PROJECT_ID: ContextVar = ContextVar(\"_GRAPHINDEX_PROJECT_ID\", default=None)\n\ndef _get_project_id() -> Optional[int]:\n    \"\"\"Get the current project ID from the request-scoped var (set during agent execution).\"\"\"\n    pid = _GRAPHINDEX_PROJECT_ID.get()\n    if pid is not None:\n        return pid\n    pid = os.environ.get(\"GRAPHINDEX_PROJECT_ID\")\n    if pid:\n        try:\n            return int(pid)\n        except (ValueError, TypeError):\n            return None\n    return None\n\ndef _run_capturing_stdout(fn, *args, **kwargs):\n    \"\"\"Run a function and capture its stdout.\n\n    Some cmd_* functions print reports to stdout. We redirect stdout\n    into a buffer so the result shows in the agent''s tool output.\n    \"\"\"\n    import io\n    import contextlib\n    buf = io.StringIO()\n    with contextlib.redirect_stdout(buf):\n        rc = fn(*args, **kwargs)\n    return rc, buf.getvalue().rstrip()\n\ndef _make_neo4j_index():\n    \"\"\"Create a Neo4jDocumentIndex from env vars.\"\"\"\n    from learning.phase9.graphindex.index_build import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef graphindex_rebuild_one(name: str, project_id: Optional[int] = None) -> str:\n    \"\"\"Re-enrich ONE existing document in the graphindex.\n\n    Uses ``learning.phase9.graphindex.index_build.cmd_rebuild_one``.\n\n    Args:\n        name: Exact document filename (use graphindex_list_docs to find names).\n        project_id: Optional project ID.\n    \"\"\"\n    # Request-scoped override (set by the chat route) takes precedence over the\n    # LLM-provided arg.\n    pid_override = _GRAPHINDEX_PROJECT_ID.get()\n    if pid_override is not None:\n        project_id = pid_override\n    elif not project_id:\n        project_id = _get_project_id()\n    if not project_id:\n        return (\"ERROR: no project_id provided.\")\n\n    try:\n        from learning.phase9.graphindex.index_build import cmd_rebuild_one, make_llm\n        idx = _make_neo4j_index()\n        llm = make_llm()\n        rc, captured = _run_capturing_stdout(cmd_rebuild_one, idx, llm, name, project_id=project_id)\n        return captured or f\"## Rebuild one: {name}\\nreturn code: {rc}\"\n    except Exception as e:\n        return f\"❌ Error rebuilding {name}: {e}\"", "args_schema": {"name": {"type": "string", "description": ""}, "project_id": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"name": {"type": "string", "description": ""}, "project_id": {"type": "string", "description": ""}}, "required": ["name"]}', 'string', NULL, '{"category": "graph", "order": 47, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-15 09:27:26.490198+00:00', '2026-11-25 17:22:15.346200+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'graphindex_rebuild_one');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 97) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 97 END, 'graphindex_rebuild_project', 'GraphIndex - Rebuild Project', 'Re-enrich EVERY document in the project.', 'python_function', 'custom', '{"function_name": "graphindex_rebuild_project", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nfrom contextvars import ContextVar\n\nimport os\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\n_GRAPHINDEX_PROJECT_ID: ContextVar = ContextVar(\"_GRAPHINDEX_PROJECT_ID\", default=None)\n\ndef _get_project_id() -> Optional[int]:\n    \"\"\"Get the current project ID from the request-scoped var (set during agent execution).\"\"\"\n    pid = _GRAPHINDEX_PROJECT_ID.get()\n    if pid is not None:\n        return pid\n    pid = os.environ.get(\"GRAPHINDEX_PROJECT_ID\")\n    if pid:\n        try:\n            return int(pid)\n        except (ValueError, TypeError):\n            return None\n    return None\n\ndef _run_capturing_stdout(fn, *args, **kwargs):\n    \"\"\"Run a function and capture its stdout.\n\n    Some cmd_* functions print reports to stdout. We redirect stdout\n    into a buffer so the result shows in the agent''s tool output.\n    \"\"\"\n    import io\n    import contextlib\n    buf = io.StringIO()\n    with contextlib.redirect_stdout(buf):\n        rc = fn(*args, **kwargs)\n    return rc, buf.getvalue().rstrip()\n\ndef _make_neo4j_index():\n    \"\"\"Create a Neo4jDocumentIndex from env vars.\"\"\"\n    from learning.phase9.graphindex.index_build import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef graphindex_rebuild_project(project_id: Optional[int] = None) -> str:\n    \"\"\"Re-enrich EVERY document in the project.\n\n    Uses ``learning.phase9.graphindex.index_build.cmd_rebuild_project``.\n    WARNING: slow! ~15s per document.\n\n    Args:\n        project_id: Optional project ID.\n    \"\"\"\n    # Request-scoped override (set by the chat route) takes precedence over the\n    # LLM-provided arg.\n    pid_override = _GRAPHINDEX_PROJECT_ID.get()\n    if pid_override is not None:\n        project_id = pid_override\n    elif not project_id:\n        project_id = _get_project_id()\n    if not project_id:\n        return (\"ERROR: no project_id provided.\")\n\n    try:\n        from learning.phase9.graphindex.index_build import cmd_rebuild_project, make_llm\n        idx = _make_neo4j_index()\n        llm = make_llm()\n        rc, captured = _run_capturing_stdout(cmd_rebuild_project, idx, llm, project_id=project_id)\n        return captured or f\"## Rebuild project (project_id={project_id})\\nreturn code: {rc}\"\n    except Exception as e:\n        return f\"❌ Error rebuilding project {project_id}: {e}\"", "args_schema": {"project_id": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"project_id": {"type": "string", "description": ""}}, "required": []}', 'string', NULL, '{"category": "graph", "order": 48, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-15 09:27:26.490200+00:00', '2026-11-25 17:22:15.346200+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'graphindex_rebuild_project');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 56) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 56 END, 'graphindex_search', 'GraphIndex - Search Documents', 'Search project documents using GraphIndex vector matching. When a scope is active (user selected docs in sidebar), only in-scope documents are searchable and loadable. Returns matching documents with context_doc_id, name, type, page count, and supporting list. Use context_doc_id with graphindex_load to get full content.', 'python_function', 'custom', '{"function_name": "graphindex_search", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nfrom contextvars import ContextVar\n\nimport os\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\n_GRAPHINDEX_DOC_SCOPE: ContextVar = ContextVar(\"_GRAPHINDEX_DOC_SCOPE\", default=None)\n\n_GRAPHINDEX_PROJECT_ID: ContextVar = ContextVar(\"_GRAPHINDEX_PROJECT_ID\", default=None)\n\ndef _get_project_id() -> Optional[int]:\n    \"\"\"Get the current project ID from the request-scoped var (set during agent execution).\"\"\"\n    pid = _GRAPHINDEX_PROJECT_ID.get()\n    if pid is not None:\n        return pid\n    pid = os.environ.get(\"GRAPHINDEX_PROJECT_ID\")\n    if pid:\n        try:\n            return int(pid)\n        except (ValueError, TypeError):\n            return None\n    return None\n\ndef graphindex_search(query: str, project_id: Optional[int] = None) -> str:\n    \"\"\"\n    用我：在某个项目的整本文档上做结构化检索（PageIndex 树，返回上下文 id）。\n    别用我：本账号上传的单个文档用 rag_search；只取某一页用 doc_index_pages。\nSearch project documents using GraphIndex vector matching.\n\n    Uses the canonical Phase 9 graphindex modules (learning.phase9.graphindex):\n      - Neo4jDocumentIndex.find_best_document for vector-based document matching\n\n    Returns matching documents with name, type, domain, and supporting list.\n    \"\"\"\n    # Request-scoped override (set by the chat route) takes precedence over the\n    # LLM-provided arg.\n    pid_override = _GRAPHINDEX_PROJECT_ID.get()\n    if pid_override is not None:\n        project_id = pid_override\n    elif not project_id:\n        project_id = _get_project_id()\n    if not project_id:\n        return (\"ERROR: no project_id provided. Either pass project_id \"\n                \"explicitly or set the GRAPHINDEX_PROJECT_ID env var.\")\n\n    try:\n        from learning.phase9.graphindex.index_build import Neo4jDocumentIndex  # noqa: E402\n\n        idx = Neo4jDocumentIndex(\n            base_url=NEO4J_HTTP_URL,\n            username=NEO4J_HTTP_USER,\n            password=NEO4J_HTTP_PASSWORD,\n        )\n        idx.ensure_constraints()\n\n        # Check if documents exist\n        docs = idx.list_documents(project_id=project_id)\n        if not docs:\n            pg_result = _search_pg_fallback(query, project_id)\n            if pg_result:\n                return pg_result\n            return f\"No documents found matching ''{query}'' in project {project_id}.\"\n\n        best = idx.find_best_document(\n            project_id=project_id,\n            query=query,\n            scope=_GRAPHINDEX_DOC_SCOPE.get(),\n        )\n        if best is None:\n            return (f\"No documents found matching ''{query}'' in project {project_id}.\")\n\n        lines = [\n            f\"## GraphIndex Search Results for: ''{query}''\",\n            \"\",\n            f\"_matching: vector (enrichment metadata)_\",\n            \"\",\n            f\"**[1] {best.name}** (BEST MATCH)\",\n            f\"    about: {best.what_this_document_is_about[:200] if best.what_this_document_is_about else ''(none)''}\",\n            f\"    supports: {(best.supported_queries or [])[:5]}\",\n            \"\",\n        ]\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error searching GraphIndex: {e}\"\n\ndef _list_docs_from_pg(project_id: int) -> list:\n    \"\"\"Query ContextDocument from PostgreSQL as a fallback catalog.\n\n    Returns list of dicts with keys: name, about, id, file_path, filename.\n    \"\"\"\n    try:\n        from db.database import SessionLocal\n        from models.core import ContextDocument\n\n        db = SessionLocal()\n        try:\n            docs = db.query(ContextDocument).filter(\n                ContextDocument.project_id == project_id,\n            ).all()\n            return [\n                {\n                    \"name\": d.filename or f\"doc_{d.id}\",\n                    \"about\": d.description or \"(no description yet — indexing in progress)\",\n                    \"id\": d.id,\n                    \"file_path\": d.file_path or \"\",\n                    \"filename\": d.filename or f\"doc_{d.id}\",\n                }\n                for d in docs\n            ]\n        finally:\n            db.close()\n    except Exception:\n        return []\n\ndef _search_pg_fallback(query: str, project_id: int) -> str:\n    \"\"\"Fallback search: list ContextDocuments from PostgreSQL and match\n    by filename. Returns a formatted result string the agent can use.\"\"\"\n    docs = _list_docs_from_pg(project_id)\n    if not docs:\n        return \"\"\n\n    # Simple match: find docs whose filename contains query keywords\n    keywords = query.lower().split()\n    matched = []\n    for d in docs:\n        name_lower = d[\"name\"].lower()\n        score = sum(1 for kw in keywords if kw in name_lower)\n        if score > 0:\n            matched.append((score, d))\n\n    matched.sort(key=lambda x: -x[0])\n\n    # If nothing matched by keyword, return the first few docs as suggestions\n    if not matched:\n        lines = [\n            f\"No exact match for ''{query}'' — showing {min(len(docs), 5)}\"\n            f\" most recently uploaded docs:\",\n            \"\",\n        ]\n        for d in docs[:5]:\n            lines.append(f\"**{d[''name'']}** (id={d[''id'']}, {d[''about''][:60]})\")\n        lines.append(\"\")\n        lines.append(\"Use `graphindex_load` with the `id` to read a document.\")\n        return \"\\n\".join(lines)\n\n    lines = [\n        f\"## GraphIndex Search Results for: ''{query}'' (PostgreSQL fallback — Neo4j enrichment may still be in progress)\",\n        \"\",\n    ]\n    for i, (score, d) in enumerate(matched, 1):\n        label = \"PRIMARY\" if i == 1 else \"SUPPORTING\"\n        lines.append(f\"**[{i}] {d[''name'']}** ({label})\")\n        lines.append(f\"   - Context Doc ID: {d[''id'']}\")\n        lines.append(f\"   - {d[''about'']}\")\n        lines.append(\"\")\n\n    lines.append(\"Use `graphindex_load(id)` to read the full content.\")\n    return \"\\n\".join(lines)", "args_schema": {"query": {"type": "string", "description": ""}, "project_id": {"type": "integer", "description": "", "default": null}}}', '{"type": "object", "properties": {"query": {"type": "string", "description": ""}, "project_id": {"type": "integer", "description": "", "default": null}}, "required": ["query"]}', 'string', NULL, '{"category": "graph", "order": 42, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034585+00:00', '2026-11-25 17:22:15.346191+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'graphindex_search');

