SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 50) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 50 END, 'grep', 'Grep', 'Search file contents for a regex pattern.

Searches through files and returns matching lines with context.

Args:
    pattern: Regular expression pattern to search for
    path: File or directory to search (default: current directory)
    file_pattern: Optional glob pattern to filter files (e.g., "*.py")

Returns:
    Matching lines with file paths and line numbers

Example:
    >>> grep("def main", path="src/")
    >>> grep("TODO", file_pattern="*.py")
    >>> grep("import.*requests", path=".", file_pattern="*.py")', 'python_function', 'custom', '{"function_name": "grep", "code": "# --- imports ---\n\nimport re\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\nimport subprocess as _subprocess\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef grep(pattern: str, path: str = \".\", file_pattern: str = None) -> str:\n    \"\"\"\n    Search file contents for a regex pattern.\n\n    Searches through files and returns matching lines with context.\n\n    Args:\n        pattern: Regular expression pattern to search for\n        path: File or directory to search (default: current directory)\n        file_pattern: Optional glob pattern to filter files (e.g., \"*.py\")\n\n    Returns:\n        Matching lines with file paths and line numbers\n\n    Example:\n        >>> grep(\"def main\", path=\"src/\")\n        >>> grep(\"TODO\", file_pattern=\"*.py\")\n        >>> grep(\"import.*requests\", path=\".\", file_pattern=\"*.py\")\n    \"\"\"\n    import re\n\n    try:\n        base_path, err = _resolve_sandbox_path(path)\n        if err:\n            return err\n\n        if not base_path.exists():\n            return f\"Error: Path not found: {path}\"\n\n        # ripgrep fast path when available (much faster on large trees).\n        import shutil as _shutil\n        import subprocess as _subprocess\n        if _shutil.which(\"rg\") is not None and base_path.is_dir():\n            try:\n                cmd = [\"rg\", \"-n\", \"--no-heading\", \"-S\", pattern]\n                if file_pattern:\n                    cmd += [\"-g\", file_pattern]\n                cmd.append(\".\")\n                proc = _subprocess.run(\n                    cmd, cwd=str(base_path), capture_output=True, text=True, timeout=30,\n                )\n                out = (proc.stdout or \"\").strip()\n                if out:\n                    lines_out = out.splitlines()\n                    capped = lines_out[:100]\n                    text = \"\\n\".join(capped)\n                    if len(lines_out) > 100:\n                        text += f\"\\n... and {len(lines_out) - 100} more matches\"\n                    return text\n            except Exception:\n                pass  # fall back to the Python implementation\n\n        # Compile regex\n        try:\n            regex = re.compile(pattern, re.IGNORECASE)\n        except re.error as e:\n            return f\"Error: Invalid regex pattern: {e}\"\n\n        results = []\n\n        # Determine files to search\n        if base_path.is_file():\n            files_to_search = [base_path]\n        else:\n            glob_pattern = file_pattern or \"**/*\"\n            files_to_search = [f for f in base_path.glob(glob_pattern) if f.is_file()]\n            # Bound the scan: cap the number of files searched per call.\n            MAX_FILES = 500\n            if len(files_to_search) > MAX_FILES:\n                files_to_search = files_to_search[:MAX_FILES]\n\n        # Search through files\n        for file_path in files_to_search:\n            try:\n                content = file_path.read_text(encoding=\"utf-8\")\n                lines = content.split(''\\n'')\n\n                for i, line in enumerate(lines, 1):\n                    # Bound per-file scan depth too.\n                    if i > 200_000:\n                        break\n                    if regex.search(line):\n                        try:\n                            rel_path = file_path.relative_to(base_path)\n                        except ValueError:\n                            rel_path = file_path.name\n                        results.append(f\"{rel_path}:{i}: {line.strip()}\")\n\n            except (UnicodeDecodeError, PermissionError):\n                # Skip binary files or files we can''t read\n                continue\n\n        if not results:\n            return f\"No matches found for pattern ''{pattern}''\"\n\n        # Limit results to prevent huge outputs\n        max_results = 100\n        if len(results) > max_results:\n            output = \"\\n\".join(results[:max_results])\n            output += f\"\\n\\n... and {len(results) - max_results} more matches\"\n        else:\n            output = \"\\n\".join(results)\n\n        logger.info(f\"Grep ''{pattern}'' found {len(results)} matches\")\n        return output\n\n    except Exception as e:\n        logger.error(f\"Error searching with pattern {pattern}: {e}\")\n        return f\"Error searching: {str(e)}\"", "args_schema": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}, "file_pattern": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}, "file_pattern": {"type": "string", "description": "", "default": null}}, "required": ["pattern"]}', 'string', NULL, '{"category": "filesystem", "order": 8, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 35, '2026-11-25 17:45:32.290068+00:00', 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034573+00:00', '2026-11-11 02:00:59.919393+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'grep');

