ve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef move_file(source: str, destination: str) -> str:\n    \"\"\"Move a file or directory to a new location.\n\n    When the destination is an existing directory, the source moves into it;\n    otherwise the destination is the target path.\n\n    Args:\n        source: Path to move from\n        destination: Target path, or an existing directory to move into\n    \"\"\"\n    src, error = _resolve_sandbox_path(source)\n    if error:\n        return error\n    dst, error = _resolve_sandbox_path(destination)\n    if error:\n        return error\n    if not src.exists():\n        return f\"Error: source ''{source}'' not found\"\n    if dst.is_dir():\n        dst = dst / src.name\n    elif dst.exists():\n        return f\"Error: destination ''{destination}'' already exists\"\n    src.rename(dst)\n    return f\"Moved ''{source}'' → ''{destination}''\"", "args_schema": {"source": {"type": "string", "description": ""}, "destination": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"source": {"type": "string", "description": ""}, "destination": {"type": "string", "description": ""}}, "required": ["source", "destination"]}', 'string', NULL, '{"category": "filesystem", "order": 11, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-15 08:02:47.985670+00:00', '2026-11-11 02:00