SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 101) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 101 END, 'neo4j_agent_tool', 'Neo4j Graph Agent', 'Ask a natural-language question and get an answer from the Neo4j graph
database (read-only).

Runs the hand-built LangGraph Neo4j agent: discovers labels and
relationships, reads schema details, generates a Cypher query,
double-checks it, executes it read-only, and explains the result.
Use for questions about nodes and relationships in the graph, e.g. "how
many people have a Python skill" or "which skills are most common".

Args:
    question: The natural-language Cypher/graph question to answer.
    database: Optional Neo4j database name to query. Empty uses the
        default (env NEO4J_DATABASE or the studio-selected database).

Returns:
    The final answer text (not raw query results).

Example:
    >>> neo4j_agent_tool("Which 3 skills are most common?", database="neo4j")', 'python_function', 'custom', '{"function_name": "neo4j_agent_tool", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef neo4j_agent_tool(question: str, database: str = \"\") -> str:\n    \"\"\"\n    Ask a natural-language question and get an answer from the Neo4j graph\n    database (read-only).\n\n    Runs the hand-built LangGraph Neo4j agent: discovers labels and\n    relationships, reads schema details, generates a Cypher query,\n    double-checks it, executes it read-only, and explains the result.\n    Use for questions about nodes and relationships in the graph, e.g. \"how\n    many people have a Python skill\" or \"which skills are most common\".\n\n    Args:\n        question: The natural-language Cypher/graph question to answer.\n        database: Optional Neo4j database name to query. Empty uses the\n            default (env NEO4J_DATABASE or the studio-selected database).\n\n    Returns:\n        The final answer text (not raw query results).\n\n    Example:\n        >>> neo4j_agent_tool(\"Which 3 skills are most common?\", database=\"neo4j\")\n    \"\"\"\n    from langgraph.tool_adapters import run_neo4j_agent\n    return run_neo4j_agent(question, database=database or None)", "args_schema": {"question": {"type": "string", "description": ""}, "database": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"question": {"type": "string", "description": ""}, "database": {"type": "string", "description": "", "default": ""}}, "required": ["question"]}', 'string', NULL, '{"category": "database", "order": 62, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-22 14:30:39.163850+00:00', '2026-11-25 17:22:15.346201+00:00', FALSE, NULL, NULL
