SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 281) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 281 END, 'ontology_verify_stage', 'Ontology Verify Stage (mechanical acceptance)', 'Verify that the rung you just delegated actually landed — mechanically, before you report it. Pass `stage` (plan | build | structure | metrics | board | publish) and the key/db it concerns: plan checks a plan file covers every sheet AND that no database was created yet; build checks the database exists with the promised row counts per table; structure/metrics/board run the repo''s own gate scripts (check_structure / check_samples / check_dashboard) plus declaration-vs-board id coverage; publish checks the profile exists and its version is registered. Read-only — it never fixes anything. A FAIL lists the named checks that failed; do not advance to the next rung, re-dispatch the expert with those names.', 'python_function', 'custom', '{"function_name": "ontology_verify_stage", "code": "# --- imports ---\ndef ontology_verify_stage(stage: str, ontology_key: str = \"\", db_name: str = \"\",\n                          plan_path: str = \"\", expect: str = \"\", sheets: str = \"\") -> str:\n    \"\"\"Check one rung of the ontology pipeline against what that rung promised.\n\n    `expect` is a JSON object of {table: rows} (used by the build stage); `sheets` is a comma-separated\n    list of sheet names (used by the plan stage). Returns PASS/FAIL plus every check that ran.\n    \"\"\"\n    import json as _json\n\n    from features.ontology import stage_checks as sc\n\n    try:\n        parsed_expect = _json.loads(expect) if str(expect or \"\").strip() else None\n    except Exception as exc:                                    # noqa: BLE001\n        return f\"ERROR: `expect` must be JSON like {{\\\"orders\\\": 4}} — {type(exc).__name__}: {exc}\"\n    sheet_list = [s.strip() for s in str(sheets or \"\").split(\",\") if s.strip()]\n\n    try:\n        out = sc.run_stage(stage, ontology_key=ontology_key, db_name=db_name,\n                           plan_path=plan_path, expect=parsed_expect, sheets=sheet_list)\n    except sc.StageCheckError as exc:\n        return f\"REFUSED: {exc}\"\n    except Exception as exc:                                    # noqa: BLE001\n        return f\"ERROR: {type(exc).__name__}: {exc}\"\n\n    lines = [f\"{out[''verdict''].upper()}  stage={out[''stage'']}\"\n             + (f\"  key={ontology_key}\" if ontology_key else \"\")\n             + (f\"  db={db_name}\" if db_name else \"\")]\n    for c in out[\"checks\"]:\n        lines.append(f\"  {''PASS'' if c[''ok''] else ''FAIL''}  {c[''name'']}\"\n                     + (f\"  —— {c[''detail'']}\" if c.get(\"detail\") else \"\"))\n    if out[\"failed\"]:\n        lines.append(\"\")\n        lines.append(\"下一步：不要往下走。把上面 FAIL 的名字带回给同一个专家重派，\"\n                     \"或者把需要人决定的部分写进 needs_human。\")\n    return \"\\n\".join(lines)\n", "args_schema": {"stage": {"type": "string", "description": "plan | build | structure | metrics | board | publish"}, "ontology_key": {"type": "string", "description": "Registered key.", "default": ""}, "db_name": {"type": "string", "description": "Database name.", "default": ""}, "plan_path": {"type": "string", "description": "Plan file path (plan stage).", "default": ""}, "expect": {"type": "string", "description": "JSON {table: rows} (build stage).", "default": ""}, "sheets": {"type": "string", "description": "Comma-separated sheets (plan stage).", "default": ""}}}', '{"type": "object", "properties": {"stage": {"type": "string", "enum": ["plan", "build", "structure", "metrics", "board", "publish"], "description": "Which rung to verify (the rung you just delegated)."}, "ontology_key": {"type": "string", "description": "Registered key, e.g. store_monthly_v1 (needed by structure / metrics / board / publish).", "default": ""}, "db_name": {"type": "string", "description": "Database the rung concerns (plan: must NOT exist yet; build: must exist with the promised rows).", "default": ""}, "plan_path": {"type": "string", "description": "Path to the plan file the `tables` expert produced (plan stage).", "default": ""}, "expect": {"type": "string", "description": "JSON object {table: rows} the build stage must match exactly.", "default": ""}, "sheets": {"type": "string", "description": "Comma-separated sheet names the plan must name (plan stage).", "default": ""}}, "required": ["stage"]}', 'string', NULL, '{"category": "ontology", "order": 0, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, NULL, FALSE, NULL, 36, '2026-11-25 17:46:45.495655+00:00', 0, NULL, '1.0.0', NULL, 'ontology', TRUE, 'false', '["ontology", "verify", "gate", "acceptance"]', '2026-11-25 13:10:04.308917+00:00', '2026-11-25 13:10:04.308917+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'ontology_verify_stage');

