SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 69) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 69 END, 'pg_list_documents', 'PG - List Documents', 'List all context documents (uploaded files) with their metadata.

Documents are the source files uploaded for RAG/GraphIndex processing.
Each document has a file_path on disk and may be indexed in Neo4j.

Args:
    project_id: Optional project ID to filter by

Returns:
    Formatted list of documents with metadata

Example:
    >>> pg_list_documents()
    >>> pg_list_documents(project_id=1)', 'python_function', 'custom', '{"function_name": "pg_list_documents", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_documents(project_id: int | None = None) -> str:\n    \"\"\"\n    List all context documents (uploaded files) with their metadata.\n\n    Documents are the source files uploaded for RAG/GraphIndex processing.\n    Each document has a file_path on disk and may be indexed in Neo4j.\n\n    Args:\n        project_id: Optional project ID to filter by\n\n    Returns:\n        Formatted list of documents with metadata\n\n    Example:\n        >>> pg_list_documents()\n        >>> pg_list_documents(project_id=1)\n    \"\"\"\n    from models.core import ContextDocument\n    db = _get_pg_session()\n    try:\n        query = db.query(ContextDocument).order_by(ContextDocument.updated_at.desc())\n        if project_id is not None:\n            query = query.filter(ContextDocument.project_id == project_id)\n        docs = query.all()\n        if not docs:\n            return \"No documents found.\" if project_id is None else f\"No documents found for project_id={project_id}.\"\n        lines = [f\"## Documents ({len(docs)} total)\", \"\"]\n        for d in docs:\n            lines.append(\n                f\"- **{d.filename}** (id={d.id})  \"\n                f\"type={d.document_type.value}  \"\n                f\"size={d.file_size}B  \"\n                f\"index={d.indexing_status.value}  \"\n                f\"project={d.project_id}\"\n            )\n            if d.description:\n                lines.append(f\"  {d.description[:150]}\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing documents: {e}\"\n    finally:\n        db.close()", "args_schema": {"project_id": {"type": "integer", "description": "", "default": null}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": "", "default": null}}, "required": []}', 'string', NULL, '{"category": "platform", "order": 37, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'platform', TRUE, NULL, '["builtin", "platform"]', '2026-08-01 14:44:18.034610+00:00', '2026-11-25 17:22:15.346194+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_documents');

