SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 77) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 77 END, 'python_execute', 'Python Execute', 'Execute Python code and return stdout + stderr.', 'python_function', 'custom', '{"function_name": "python_execute", "code": "# --- imports ---\n\nimport os as _os\n\nimport sys as _sys\n\nimport subprocess as _subprocess\n\nimport tempfile as _tempfile\n\nimport textwrap as _textwrap\n\ndef python_execute(code: str, timeout: int = 30) -> str:\n    \"\"\"\n    Execute Python code and return stdout + stderr.\n\n    **不可以用它连数据库**：解析文件、算数、生成报告、跑编译与门禁都可以；\n    `psql` / `psycopg2` / `sqlalchemy` / `connect(...dbname)` 会被拒绝——\n    数据只走 `db_query_agent` / `db_query_langgraph` / `db_execute` / `db_describe`。\n\n    WARNING: Code runs in the same process. Only trusted agents should call this.\n\n    Args:\n        code: Python code to execute\n        timeout: Max execution time in seconds\n\n    Returns:\n        Combined stdout and stderr output.\n    \"\"\"\n    from core.tools.db_guard import refusal as _db_refusal\n\n    _blocked = _db_refusal(code or \"\")\n    if _blocked is not None:\n        return _blocked\n    try:\n        # Wrap code to capture stdout\n        wrapper_code = (\n            \"import sys, io, traceback\\n\"\n            \"_buffer = io.StringIO()\\n\"\n            \"sys.stdout = _buffer\\n\"\n            \"sys.stderr = _buffer\\n\"\n            \"try:\\n\"\n            + _textwrap.indent(code, ''    '') + \"\\n\"\n            \"except Exception:\\n\"\n            \"    traceback.print_exc()\\n\"\n            \"finally:\\n\"\n            \"    sys.stdout = sys.__stdout__\\n\"\n            \"    sys.stderr = sys.__stderr__\\n\"\n            \"    print(_buffer.getvalue(), end='''')\\n\"\n        )\n        with _tempfile.TemporaryDirectory() as tmpdir:\n            result = _subprocess.run(\n                # -I = isolated mode: ignores PYTHON* env vars and user\n                # site-packages; cwd is a throwaway temp dir so the code can''t\n                # read/write repo files by relative path.\n                [_sys.executable, \"-I\", \"-c\", wrapper_code],\n                capture_output=True,\n                text=True,\n                timeout=timeout,\n                cwd=tmpdir,\n                env={k: v for k, v in _os.environ.items() if k in (\"PATH\", \"HOME\", \"TEMP\", \"TMPDIR\")}\n            )\n        output = result.stdout or \"\"\n        if result.stderr:\n            output += f\"\\n--- stderr ---\\n{result.stderr}\"\n        if result.returncode != 0 and not output:\n            output = f\"❌ Exit code: {result.returncode}\"\n        return output if output else \"✅ Code executed (no output)\"\n    except _subprocess.TimeoutExpired:\n        return f\"❌ Timed out after {timeout}s\"\n    except Exception as e:\n        return f\"❌ Execution Error: {e}\"", "args_schema": {"code": {"type": "string", "description": ""}, "timeout": {"type": "integer", "description": "", "default": 30}}}', '{"type": "object", "properties": {"code": {"type": "string", "description": ""}, "timeout": {"type": "integer", "description": "", "default": 30}}, "required": ["code"]}', 'string', NULL, '{"category": "analysis", "order": 60, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 2, '2026-11-25 13:53:49.611375+00:00', 0, NULL, '1.0.0', NULL, 'data', TRUE, NULL, '["builtin", "data"]', '2026-08-01 14:44:18.034625+00:00', '2026-11-25 17:22:15.346195+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'python_execute');

