SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 220) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 220 END, 'rag_index', 'RAG - Index Documents', '用我：把【本账号】的文档切块、嵌入、写进检索集合（rag_search 搜的就是它）。', 'python_function', 'custom', '{"function_name": "rag_index", "code": "# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\nasync def rag_index(path: str, reset: bool = False) -> str:\n    \"\"\"\n    用我：把【本账号】的文档切块、嵌入、写进检索集合（rag_search 搜的就是它）。\n    别用我：只是想读一份文件的内容，用 read_file；查平台库用 pg_query。\nIndex a file or folder into this account''s retrieval collection.\n\n    This is the step between \"the file exists\" and \"`rag_search` can find it\". It is\n    a TOOL rather than only a script (`scripts/rag_index.py`) because the document-QA\n    agent is the one place retrieval is taught: without this half, the agent could\n    say \"nothing is indexed yet\" and had no way to fix that.\n\n    Cost, stated up front so the model can decide: every chunk becomes one local\n    embedding call. A 20-page PDF is ~200 chunks; that is minutes, not seconds, and\n    the turn waits for it. Index once, then ask many questions.\n\n    Idempotency: chunk ids are content-derived, so re-indexing the same unchanged\n    file updates its chunks instead of duplicating them. `reset=true` drops the\n    collection first — the honest choice after editing a document, because\n    otherwise the old chunks of deleted text stay retrievable.\n\n    Args:\n        path: File or folder path. Relative paths resolve against the backend\n            directory. Folders are walked for .pdf/.txt/.md/.csv/.log/.html.\n        reset: Drop this account''s collection before indexing.\n\n    Returns:\n        A one-line report: how many files, how many chunks, how long, and which\n        collection it wrote to — the numbers that later explain a vague answer.\n    \"\"\"\n    from core.context.current_user import current_user_id\n\n    try:\n        user_id = current_user_id()\n        if user_id is None:\n            return \"No account context for this run, so there is no collection to write to.\"\n        from core.rag import index_file\n        from pathlib import Path as _Path\n\n        target = _Path(path).expanduser()\n        if not target.is_absolute():\n            from services import user_roots\n\n            backend_dir = _Path(user_roots.install_root()).parent\n            target = (backend_dir / target).resolve()\n        if not target.exists():\n            return f\"Not found: {target}. Indexing needs a real file or folder.\"\n\n        import time as _time\n\n        started = _time.time()\n        report = index_file(user_id, str(target), reset=bool(reset))\n        elapsed = _time.time() - started\n        return (\n            f\"Indexed {report.get(''documents'', 1)} file(s) → {report.get(''chunks'', 0)} chunks \"\n            f\"in {elapsed:.0f}s into {report.get(''collection'')}. \"\n            f\"Now call rag_search before answering questions about this document.\"\n        )\n    except Exception as exc:  # noqa: BLE001 — an indexing failure is not a turn failure\n        logger.warning(\"rag_index failed: %s\", exc)\n        return f\"Indexing failed: {exc}. Say so rather than answering from memory.\"", "args_schema": {"path": {"type": "string", "description": ""}, "reset": {"type": "boolean", "description": "", "default": false}}}', '{"type": "object", "properties": {"path": {"type": "string", "description": ""}, "reset": {"type": "boolean", "description": "", "default": false}}, "required": ["path"]}', 'string', NULL, '{"category": "graph", "order": 51, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-11-04 12:17:29.720617+00:00', '2026-11-25 17:22:15.346207+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'rag_index');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 182) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 182 END, 'rag_search', 'RAG - Search Documents', '用我：检索【本账号上传的文档】的段落（向量检索），答案要标来源。', 'python_function', 'custom', '{"function_name": "rag_search", "code": "# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\nasync def rag_search(query: str, k: int = 4) -> str:\n    \"\"\"\n    用我：检索【本账号上传的文档】的段落（向量检索），答案要标来源。\n    别用我：查平台库用 pg_query；要整本文档的目录结构用 graphindex_*。\nSearch the documents this account has indexed, by meaning.\n\n    This is the tutorial''s retrieval step exposed as a tool:\n    https://docs.langchain.com/oss/python/langchain/knowledge-base\n\n    Returns the nearest passages with their **source and page**, so the model can\n    cite where a claim came from. The header says out loud that these are the only\n    passages available: a retrieval tool whose output looks like a general answer\n    invites the model to continue from its own memory, which is the failure the\n    document-chat case exists to expose.\n\n    Scoped to the caller''s own collection (`lc_kb_u<id>`), so an agent cannot search\n    another account''s documents — the collection is chosen from the identity, never\n    from an argument.\n\n    Args:\n        query: What to look for, in natural language. Not keywords — this is a\n            semantic search, so the question the user asked is a valid query.\n        k: How many passages to return (1-20, default 4). More passages means more\n            context but a weaker signal-to-noise ratio; if the answer is \"vague\",\n            raise this, and if it is \"wrong\", lower it.\n\n    Returns:\n        Numbered passages with `source p.<page>` labels and a distance score, or an\n        explanation of why there is nothing to search.\n    \"\"\"\n    from core.context.current_user import current_user_id\n\n    try:\n        user_id = current_user_id()\n        if user_id is None:\n            return (\n                \"No account context for this run, so no document index to search. \"\n                \"Do not answer from memory — say the documents could not be searched.\"\n            )\n        from core.rag import has_index, search_with_scores\n\n        if not has_index(user_id):\n            return (\n                \"No documents are indexed for this account yet. Index a document \"\n                \"first; until then say you cannot search the documents rather than \"\n                \"answering from your own knowledge.\"\n            )\n        pairs = search_with_scores(user_id, query, k=max(1, min(int(k or 4), 20)))\n    except Exception as exc:  # noqa: BLE001 — a retrieval failure is not a turn failure\n        logger.warning(\"rag_search failed: %s\", exc)\n        return f\"Document search failed: {exc}. Do not answer from memory — tell the user the search failed.\"\n\n    if not pairs:\n        return \"No passages matched this query. Say the documents do not cover it.\"\n\n    lines = [\n        f\"{len(pairs)} passage(s) from the indexed documents. These are the ONLY \"\n        \"passages available: cite them by number, and if they do not answer the \"\n        \"question say so instead of filling the gap yourself.\",\n        \"\",\n    ]\n    for i, (doc, distance) in enumerate(pairs, start=1):\n        md = doc.metadata or {}\n        source = md.get(\"source\") or \"unknown\"\n        page = f\" p.{md[''page'']}\" if md.get(\"page\") else \"\"\n        text = \"\\n\".join(line.rstrip() for line in (doc.page_content or \"\").splitlines()).strip()\n        lines.append(f\"[{i}] {source}{page} (distance {float(distance):.3f})\\n{text}\")\n        lines.append(\"\")\n    return \"\\n\".join(lines).strip()", "args_schema": {"query": {"type": "string", "description": ""}, "k": {"type": "integer", "description": "", "default": 4}}}', '{"type": "object", "properties": {"query": {"type": "string", "description": ""}, "k": {"type": "integer", "description": "", "default": 4}}, "required": ["query"]}', 'string', NULL, '{"category": "graph", "order": 50, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-10-30 15:22:17.361238+00:00', '2026-11-25 17:22:15.346204+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'rag_search');

