SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 111) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 111 END, 'read_any_file', 'Read Any File (unified reader)', 'Read any file and return its TEXT - one reader for four kinds of file (text, image, PDF, Office documents including Excel, and archives). TEXT (markdown, code, data): verbatim, line-numbered. IMAGE (.png/.jpg/.jpeg/.webp/.gif/.bmp/.tiff): a short vision description plus the OCR-extracted text. PDF: read page by page - a page with a real text layer gives its text, and a page that is only a scan is rendered and OCR''d, so scanned contracts and invoices work. WORD/POWERPOINT (.docx/.pptx): read through python-docx / python-pptx - headings, lists, tables and slide speaker notes are kept, and every embedded picture is read with OCR (and described when vision is on), so a document that is mostly screenshots still reads. EXCEL (.xlsx/.xlsm): every sheet is read through openpyxl - cell values as | separated rows, sheet by sheet, with the sheet names and hidden sheets marked. ARCHIVE (.zip/.tar/.tar.gz/.tgz): the members are listed with sizes, and every member whose type this tool understands is read too - a .csv inside a zip comes back as text, a .docx as a document, a .png OCR''d. Limits keep it predictable: the first 15 readable members, 256 KiB per member, 2 MiB in total, one level of nesting, and a member whose declared size breaks a limit is refused before it is decompressed. Everything skipped is named with its reason. It never returns raw or base64 image data, so it cannot overflow the context - use it instead of read_file for images, scans and pictures inside documents. OCR uses the language packs installed on the host (English and Chinese by default), so a scanned Chinese page reads as Chinese. Pass `question` to ask something specific about an image, a scanned page or a picture; `vision=False` for a deterministic OCR-only read (faster, no model call); `vision_model` to pick which model performs that read (defaults to the platform''s configured vision model).', 'python_function', 'custom', '{"function_name": "read_any_file", "code": "# --- imports ---\nimport sys as _sys\nfrom pathlib import Path as _Path\n\n\ndef _ensure_app_importable() -> None:\n    \"\"\"Make backend/ importable even when the exec namespace lacks cwd context.\"\"\"\n    try:\n        backend = str(BACKEND)\n    except NameError:  # no __file__ in this namespace\n        return\n    if backend not in _sys.path:\n        _sys.path.insert(0, backend)\n\n\nasync def read_any_file(file_path: str, question: str = None, vision: bool = True,\n                        vision_model: str = None) -> str:\n    \"\"\"Read any file and return TEXT - never raw or base64 bytes.\n\n    One reader, four kinds of file:\n\n    text (md, code, data) -> verbatim, line-numbered\n    image                 -> vision description + OCR text (vision=False: OCR only)\n    pdf                   -> page by page: a page with a text layer comes back as\n                             text; a page that is only a scan is rendered and read\n                             with OCR (and described by the vision model)\n    word / powerpoint     -> structure through python-docx / python-pptx (headings,\n                             lists, tables, slide notes) plus every embedded picture\n                             read with OCR (and vision)\n    excel (.xlsx)         -> cell values sheet by sheet through openpyxl (a formula\n                             shows its cached result, else the formula itself)\n    archive (.zip/.tar.*) -> the list of members, then every readable member read\n                             by this same reader (a .docx inside a zip comes back\n                             as a document, a .csv as text, a .png OCR''d)\n    \"\"\"\n    _ensure_app_importable()\n    from core.graphs.read_file import read_file_as_text\n\n    return await read_file_as_text(file_path, question=question, vision_enabled=vision,\n                                   vision_model=vision_model)\n", "args_schema": {"file_path": {"type": "string", "description": "Path to the file to read (text, image, PDF, Word or PowerPoint)."}, "question": {"type": "string", "description": "Optional question about an image (ignored for text files).", "default": ""}, "vision": {"type": "boolean", "description": "Images: false = OCR text only, skipping the vision model (default true).", "default": true}, "vision_model": {"type": "string", "description": "Vision model used for images (e.g. deepseek-flash). Empty = platform default.", "default": ""}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": "Path to the file to read (text, image, PDF, Word or PowerPoint)."}, "vision": {"type": "boolean", "description": "Images: false = OCR text only, skipping the vision model (default true).", "default": true}, "vision_model": {"type": "string", "description": "Vision model used for images (e.g. deepseek-flash). Empty = platform default.", "default": ""}, "question": {"type": "string", "description": "Optional question about an image (ignored for text files).", "default": ""}}, "required": ["file_path"]}', 'string', NULL, '{"category": "filesystem", "order": 6, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, NULL, FALSE, NULL, 27, '2026-11-25 16:43:36.337862+00:00', 2, '2026-10-12 11:44:12.051701+00:00', '1.0.0', NULL, 'filesystem', TRUE, 'false', '["filesystem", "image", "ocr", "vision"]', '2026-10-12 11:43:45.448387+00:00', '2026-11-25 04:49:57.911176+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'read_any_file');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 46) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 46 END, 'read_file', 'Read File', '用我：读工作区里的文本文件（可带 offset/limit）。
别用我：pdf/docx/pptx 等多格式文档用 read_any_file；图片用 read_image。

Read the contents of a file with optional line offset and limit.

Supports plain text files (.txt, .md, .py, .json, .csv, etc.) plus
binary documents: PDF (.pdf), Word (.docx), PowerPoint (.pptx) and Excel
(.xlsx).
Binary formats are converted to text (line-numbered like any other file):
a .docx keeps its headings, lists and tables, a .pptx keeps its slides and
speaker notes, and a .xlsx comes back sheet by sheet with its cell values.

Embedded pictures cannot be read here - they are pixels, not text - but the
output says how many there are, and `read_any_file` reads them (OCR, plus a
description from the vision model).
Legacy .ppt / .doc (pre-2007) and spreadsheets are not supported - convert
them first (.docx / .pptx, or .csv for a sheet).

Args:
    file_path: Path to the file to read
    offset: Line number to start reading from (0-indexed, default: 0)
    limit: Maximum number of lines to read (default: None for all lines)
    max_chars: Maximum characters to read (default: 500000)

Returns:
    File contents with line numbers

Example:
    >>> read_file("src/main.py")
    >>> read_file("logs/app.log", offset=100, limit=50)
    >>> read_file("report.pdf")
    >>> read_file("slides.pptx")', 'python_function', 'custom', '{"function_name": "read_file", "code": "# --- imports ---\n\nimport re\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\n_SKILL_PATH = re.compile(r\"(?:^|/)skills/(?:builtin|personal(?:/[^/]+)?)/([a-z0-9][a-z0-9-]*)/SKILL\\.md$\")\n\ndef _skill_id_from_path(path: str) -> str | None:\n    \"\"\"The skill id if this path is a skill''s SKILL.md, else None.\n\n    Deliberately narrow: `skills/<builtin|personal>/<id>/SKILL.md`, with the personal root allowed one extra\n    segment for the account. A file that merely lives under a folder called `skills` is not a skill read.\n    \"\"\"\n    match = _SKILL_PATH.search(path.replace(\"\\\\\", \"/\"))\n    return match.group(1) if match else None\n\ndef read_file(file_path: str, offset: int = 0, limit: int = None, max_chars: int = 500_000) -> str:\n    \"\"\"\n    用我：读工作区里的文本文件（可带 offset/limit）。\n    别用我：pdf/docx/pptx 等多格式文档用 read_any_file；图片用 read_image。\n\n    Read the contents of a file with optional line offset and limit.\n\n    Supports plain text files (.txt, .md, .py, .json, .csv, etc.) plus\n    binary documents: PDF (.pdf), Word (.docx), PowerPoint (.pptx) and Excel\n    (.xlsx).\n    Binary formats are converted to text (line-numbered like any other file):\n    a .docx keeps its headings, lists and tables, a .pptx keeps its slides and\n    speaker notes, and a .xlsx comes back sheet by sheet with its cell values.\n\n    Embedded pictures cannot be read here - they are pixels, not text - but the\n    output says how many there are, and `read_any_file` reads them (OCR, plus a\n    description from the vision model).\n    Legacy .ppt / .doc (pre-2007) and spreadsheets are not supported - convert\n    them first (.docx / .pptx, or .csv for a sheet).\n\n    Args:\n        file_path: Path to the file to read\n        offset: Line number to start reading from (0-indexed, default: 0)\n        limit: Maximum number of lines to read (default: None for all lines)\n        max_chars: Maximum characters to read (default: 500000)\n\n    Returns:\n        File contents with line numbers\n\n    Example:\n        >>> read_file(\"src/main.py\")\n        >>> read_file(\"logs/app.log\", offset=100, limit=50)\n        >>> read_file(\"report.pdf\")\n        >>> read_file(\"slides.pptx\")\n    \"\"\"\n    try:\n        path, err = _resolve_sandbox_path(file_path)\n        if err:\n            return err\n\n        if not path.exists():\n            return f\"Error: File not found: {file_path}\"\n\n        if not path.is_file():\n            return f\"Error: Path is not a file: {file_path}\"\n\n        # A skill''s SKILL.md is read as a plain file in the sandbox mirror (`skills/<type>/<id>/SKILL.md`), so\n        # counting only the `skill` tool left the common path uncounted — the reason the UI read \"0 uses\" for a\n        # library that agents had been reading all along.\n        _skill_id = _skill_id_from_path(str(path))\n        if _skill_id:\n            try:\n                from core.skills.registry import get_skill_registry\n                get_skill_registry().record_usage(_skill_id, \"automatic\", \"success\", source=\"read_file\")\n            except Exception:               # counting must never fail a read\n                pass\n\n        # Binary document formats are converted to plain text first; the\n        # line-numbering / offset / limit logic below applies to all formats.\n        ext = path.suffix.lower()\n        if ext == \".pdf\":\n            content = _extract_pdf_text(path)\n        elif ext == \".docx\":\n            content = _extract_docx_text(path)\n        elif ext == \".pptx\":\n            content = _extract_pptx_text(path)\n        elif ext in (\".xlsx\", \".xlsm\"):\n            content = _extract_xlsx(path)[0] or \"Error: no data found in workbook\"\n        elif ext in (\".ppt\", \".doc\", \".xls\"):\n            # 老格式走 services/legacy_doc.py 的共享转换链(同一份实现,\n            # 聊天上传那条路也用它)。转不出来才报错,而且报错要能照着做。\n            from services.legacy_doc import legacy_to_text, unsupported_hint\n            content, _who = legacy_to_text(path)\n            if not content.strip():\n                return unsupported_hint(ext)\n        else:\n            # Bounded read: never slurp an arbitrarily large file into memory\n            # before truncating. The 2MB ceiling is generous and the offset /\n            # limit / max_chars slicing below still applies on top of it.\n            MAX_READ_BYTES = 2 * 1024 * 1024\n            with path.open(\"r\", encoding=\"utf-8\", errors=\"replace\") as fh:\n                content = fh.read(MAX_READ_BYTES + 1)\n            if len(content) > MAX_READ_BYTES:\n                content = content[:MAX_READ_BYTES] + \"\\n...[file too large to read in full; truncated]...\"\n        lines = content.split(''\\n'')\n\n        # Apply offset and limit\n        if offset > 0:\n            lines = lines[offset:]\n        if limit is not None:\n            lines = lines[:limit]\n\n        # Add line numbers\n        start_line = offset + 1\n        numbered_lines = [f\"{start_line + i:4d}| {line}\" for i, line in enumerate(lines)]\n        result = ''\\n''.join(numbered_lines)\n\n        if len(result) > max_chars:\n            result = result[:max_chars] + f\"\\n\\n[Truncated - content exceeds {max_chars} characters]\"\n\n        logger.info(f\"Read file: {file_path} ({len(lines)} lines)\")\n        return result\n\n    except UnicodeDecodeError:\n        return f\"Error: File is not a text file or uses unsupported encoding\"\n    except Exception as e:\n        logger.error(f\"Error reading file {file_path}: {e}\")\n        return f\"Error reading file: {str(e)}\"\n\ndef _extract_pdf_text(path: Path) -> str:\n    \"\"\"Extract readable text from a PDF, grouped page by page.\"\"\"\n    try:\n        from pypdf import PdfReader\n    except ImportError:\n        return \"Error: pypdf is not installed. Run: pip install pypdf\"\n    reader = PdfReader(str(path))\n    pages = []\n    for i, page in enumerate(reader.pages, start=1):\n        text = (page.extract_text() or \"\").strip()\n        if text:\n            pages.append(f\"[Page {i}]\\n{text}\")\n    return \"\\n\\n\".join(pages) if pages else \"Error: no extractable text found in PDF\"\n\ndef _docx_pictures(document_or_path, with_blobs: bool = True) -> list:\n    \"\"\"Embedded pictures in a .docx, in document order.\n\n    Returns ``[{index, label, anchor, ext, bytes[, blob]}]``. python-docx exposes\n    inline shapes without saying *where* they sat, so the pictures are walked\n    from the document XML — which also finds pictures inside table cells and text\n    boxes. ``anchor`` is the text of the picture''s own paragraph (or the last\n    paragraph before it), which is what lets a reader say where a picture was.\n\n    Takes an open ``docx.Document`` or a path, so a caller that already has the\n    document open does not pay for a second one.\n    \"\"\"\n    try:\n        from docx.oxml.ns import qn\n    except ImportError:\n        return []\n    document = document_or_path\n    if not hasattr(document, \"element\"):\n        import docx as _docx\n\n        document = _docx.Document(str(document_or_path))\n\n    pictures = []\n    last_text = \"\"\n    for paragraph in document.element.body.iter(qn(\"w:p\")):\n        text = \"\".join(node.text or \"\" for node in paragraph.iter(qn(\"w:t\"))).strip()\n        for blip in paragraph.iter(qn(\"a:blip\")):\n            rid = blip.get(qn(\"r:embed\")) or blip.get(qn(\"r:link\"))\n            if not rid:\n                continue\n            part = document.part.related_parts.get(rid)\n            blob = getattr(part, \"blob\", None) if part is not None else None\n            if not blob:\n                continue\n            entry = {\n                \"index\": len(pictures),\n                \"label\": f\"[Picture {len(pictures) + 1}]\",\n                \"anchor\": (text or last_text or \"no surrounding text\")[:120],\n                \"ext\": Path(str(getattr(part, \"partname\", \"\"))).suffix.lower() or \".png\",\n                \"bytes\": len(blob),\n            }\n            if with_blobs:\n                entry[\"blob\"] = blob\n            pictures.append(entry)\n        if text:\n            last_text = text\n    return pictures\n\ndef _extract_docx(path: Path, with_blobs: bool = False):\n    \"\"\"``(text, pictures)`` from one .docx, from a single open.\n\n    The text keeps the document''s own structure — a heading stays a heading, a\n    list item a bullet, a table a table — because flattening it to bare\n    paragraphs throws away the only outline a .docx has. Pictures cannot be read\n    here (they are pixels, not text): they are inventoried, and the caller that\n    can read them does — ``read_any_file`` OCRs them and describes them.\n    \"\"\"\n    import docx\n\n    document = docx.Document(str(path))\n    lines: List[str] = []\n    for paragraph in document.paragraphs:\n        text = (paragraph.text or \"\").strip()\n        if not text:\n            continue\n        style = (paragraph.style.name if paragraph.style is not None else \"\") or \"\"\n        if style.startswith(\"Heading\"):\n            level = \"\".join(ch for ch in style if ch.isdigit()) or \"1\"\n            lines.append(f\"{''#'' * min(int(level), 6)} {text}\")\n        elif style.startswith(\"List\") or style in (\"List Bullet\", \"List Number\"):\n            lines.append(f\"- {text}\")\n        else:\n            lines.append(text)\n    for table in document.tables:\n        rows = []\n        for row in table.rows:\n            cells = [cell.text.strip() for cell in row.cells]\n            if any(cells):\n                rows.append(\" | \".join(cells))\n        if rows:\n            lines.append(\"[Table]\")\n            lines.extend(rows)\n\n    return \"\\n\".join(lines), _docx_pictures(document, with_blobs=with_blobs)\n\nXLSX_MAX_ROWS = int(os.getenv(\"LANGCONFIG_XLSX_MAX_ROWS\", \"200\"))\n\nXLSX_MAX_COLS = int(os.getenv(\"LANGCONFIG_XLSX_MAX_COLS\", \"40\"))\n\nXLSX_MAX_SHEETS = int(os.getenv(\"LANGCONFIG_XLSX_MAX_SHEETS\", \"10\"))\n\nXLSX_CELL_MAX_CHARS = int(os.getenv(\"LANGCONFIG_XLSX_CELL_MAX_CHARS\", \"200\"))\n\ndef _cell_text(value) -> str:\n    \"\"\"One cell as the text a reader should see (not ``25.0`` for 25).\"\"\"\n    import datetime as _dt\n\n    if value is None:\n        return \"\"\n    if isinstance(value, bool):\n        return \"TRUE\" if value else \"FALSE\"\n    if isinstance(value, _dt.datetime):\n        return value.date().isoformat() if value.time() == _dt.time(0, 0) else value.isoformat(sep=\" \")\n    if isinstance(value, _dt.date):\n        return value.isoformat()\n    if isinstance(value, float):\n        if value.is_integer() and abs(value) < 1e15:\n            return str(int(value))\n        return f\"{value:g}\"\n    text = str(value).replace(\"\\n\", \" \").strip()\n    return text[:XLSX_CELL_MAX_CHARS]\n\ndef _xlsx_media(path: Path) -> tuple:\n    \"\"\"``(images, charts)`` inside the .xlsx zip — counted, never rendered.\"\"\"\n    try:\n        import zipfile\n\n        with zipfile.ZipFile(path) as archive:\n            names = archive.namelist()\n        return (sum(1 for n in names if n.startswith(\"xl/media/\")),\n                sum(1 for n in names if n.startswith(\"xl/charts/chart\")))\n    except Exception:\n        return (0, 0)\n\ndef _extract_xlsx(path: Path, with_blobs: bool = False):\n    \"\"\"``(text, [])`` from one .xlsx, sheet by sheet.\n\n    A spreadsheet is a grid, not prose: each sheet becomes a heading and each row\n    a ``|``-separated line, so the columns still line up for whoever reads it.\n\n    Cells are read twice on purpose: once for calculated values and once for the\n    formulas. A workbook Excel saved carries cached results, so the value pass is\n    what a reader wants; a workbook written by code (openpyxl, pandas) usually\n    carries **no** cached results, and then a formula cell is empty — which would\n    silently drop whole columns. Where the value pass has nothing, the formula is\n    shown instead. Pictures and charts are not read (a chart is not an image until\n    something renders it) but they are counted and named.\n    \"\"\"\n    from openpyxl import load_workbook\n\n    def read(data_only: bool):\n        workbook = load_workbook(str(path), data_only=data_only, read_only=True)\n        try:\n            sheets = []\n            for index, sheet in enumerate(workbook.worksheets):\n                if index >= XLSX_MAX_SHEETS:\n                    break\n                rows = []\n                for row in sheet.iter_rows(max_row=XLSX_MAX_ROWS + 1,\n                                           max_col=XLSX_MAX_COLS, values_only=True):\n                    rows.append([_cell_text(cell) for cell in row])\n                sheets.append({\n                    \"title\": sheet.title,\n                    \"hidden\": getattr(sheet, \"sheet_state\", \"visible\") != \"visible\",\n                    \"rows\": rows,\n                })\n            return sheets, max(0, len(workbook.worksheets) - XLSX_MAX_SHEETS)\n        finally:\n            workbook.close()\n\n    values, extra_sheets = read(data_only=True)\n    formulas, _ = read(data_only=False)\n\n    sections, total_rows = [], 0\n    for sheet, formula_sheet in zip(values, formulas):\n        formula_rows = formula_sheet[\"rows\"]\n        lines, overflow = [], False\n        for number, row in enumerate(sheet[\"rows\"]):\n            if number >= XLSX_MAX_ROWS:\n                overflow = True\n                break\n            fallback = formula_rows[number] if number < len(formula_rows) else []\n            merged = []\n            for column, cell in enumerate(row):\n                if not cell and column < len(fallback) and fallback[column].startswith(\"=\"):\n                    cell = fallback[column]          # no cached result: show the formula\n                merged.append(cell)\n            while merged and merged[-1] == \"\":\n                merged.pop()\n            if any(merged):\n                lines.append(\" | \".join(merged))\n        title = f\"[Sheet: {sheet[''title'']}{'' (hidden)'' if sheet[''hidden''] else ''''}]\"\n        if overflow:\n            lines.append(f\"... (more rows not shown: this sheet is longer than \"\n                         f\"{XLSX_MAX_ROWS} rows)\")\n        total_rows += len(lines) - (1 if overflow else 0)\n        sections.append(title + \"\\n\" + (\"\\n\".join(lines) if lines else \"(no data)\"))\n\n    if total_rows == 0:                # every sheet empty: nothing to hand back\n        return \"\", []\n\n    notes = []\n    if extra_sheets:\n        notes.append(f\"[{extra_sheets} more sheet(s) not shown: only the first \"\n                     f\"{XLSX_MAX_SHEETS} are read]\")\n    images, charts = _xlsx_media(path)\n    if images or charts:\n        notes.append(f\"[Media: {images} image(s), {charts} chart(s) embedded — a spreadsheet''s \"\n                     f\"pictures and charts are not rendered here]\")\n    return \"\\n\\n\".join([*sections, *notes]), []\n\ndef _picture_note(pictures: list) -> str:\n    \"\"\"Tell a text-only caller that pictures exist and who can read them.\n\n    Only ``read_file`` and the SDK path get this: they extract text and cannot\n    see pixels, so they must at least say the pixels are there. The reader that\n    *does* read them appends its own sections instead.\n    \"\"\"\n    if not pictures:\n        return \"\"\n    return (f\"[Pictures: {len(pictures)} embedded picture(s) — their text and content are \"\n            f\"not in this file''s text; read them with read_any_file]\")\n\ndef _extract_docx_text(path: Path) -> str:\n    \"\"\"Extract text from a Word .docx: headings, lists, paragraphs, then tables.\"\"\"\n    try:\n        text, pictures = _extract_docx(path)\n    except ImportError:\n        return \"Error: python-docx is not installed. Run: pip install python-docx\"\n    note = _picture_note(pictures)\n    joined = \"\\n\".join(part for part in (text, note) if part)\n    return joined or \"Error: no text found in document\"\n\ndef _pptx_pictures(presentation_or_path, with_blobs: bool = True) -> list:\n    \"\"\"Pictures in a .pptx, in slide order: ``[{index, label, anchor, …}]``.\n\n    Walks into groups, because a picture inside a grouped shape is still a\n    picture. Takes an open ``Presentation`` or a path.\n    \"\"\"\n    try:\n        from pptx.enum.shapes import MSO_SHAPE_TYPE\n    except ImportError:\n        return []\n    presentation = presentation_or_path\n    if not hasattr(presentation, \"slides\"):\n        from pptx import Presentation\n\n        presentation = Presentation(str(presentation_or_path))\n\n    def walk(shapes):\n        for shape in shapes:\n            yield shape\n            try:\n                grouped = shape.shape_type == MSO_SHAPE_TYPE.GROUP\n            except Exception:\n                grouped = False\n            if grouped:\n                yield from walk(shape.shapes)\n\n    pictures = []\n    for number, slide in enumerate(presentation.slides, start=1):\n        for shape in walk(slide.shapes):\n            try:\n                if shape.shape_type != MSO_SHAPE_TYPE.PICTURE:\n                    continue\n                image = shape.image\n                blob = image.blob\n            except Exception:\n                continue\n            entry = {\n                \"index\": len(pictures),\n                \"label\": f\"[Picture {len(pictures) + 1}]\",\n                \"anchor\": f\"slide {number}\",\n                \"ext\": \".\" + (getattr(image, \"ext\", \"\") or \"png\").lower(),\n                \"bytes\": len(blob),\n            }\n            if with_blobs:\n                entry[\"blob\"] = blob\n            pictures.append(entry)\n    return pictures\n\ndef _extract_pptx(path: Path, with_blobs: bool = False):\n    \"\"\"``(text, pictures)`` from one .pptx, from a single open.\n\n    Slide text, tables and **speaker notes** — the notes are usually where the\n    substance is, and the legacy extractor dropped them.\n    \"\"\"\n    from pptx import Presentation\n\n    prs = Presentation(str(path))\n    slides = []\n    for i, slide in enumerate(prs.slides, start=1):\n        parts = [f\"[Slide {i}]\"]\n        for shape in slide.shapes:\n            if shape.has_text_frame:\n                text = shape.text_frame.text.strip()\n                if text:\n                    parts.append(text)\n            elif getattr(shape, \"has_table\", False) and shape.has_table:\n                for row in shape.table.rows:\n                    cells = [cell.text.strip() for cell in row.cells]\n                    if any(cells):\n                        parts.append(\" | \".join(cells))\n        notes = \"\"\n        try:\n            if slide.has_notes_slide:\n                frame = slide.notes_slide.notes_text_frame\n                notes = (frame.text or \"\").strip() if frame is not None else \"\"\n        except Exception as e:  # a broken notes part must not fail the read\n            logger.debug(f\"no speaker notes for slide {i}: {e}\")\n        if notes:\n            parts.append(f\"[Speaker notes]\\n{notes}\")\n        slides.append(\"\\n\".join(parts))\n\n    return \"\\n\\n\".join(slides), _pptx_pictures(prs, with_blobs=with_blobs)\n\ndef _extract_pptx_text(path: Path) -> str:\n    \"\"\"Extract text from a PowerPoint .pptx, slide by slide, notes included.\"\"\"\n    try:\n        text, pictures = _extract_pptx(path)\n    except ImportError:\n        return \"Error: python-pptx is not installed. Run: pip install python-pptx\"\n    note = _picture_note(pictures)\n    joined = \"\\n\\n\".join(part for part in (text, note) if part)\n    return joined or \"Error: no text found in presentation\"", "args_schema": {"file_path": {"type": "string", "description": ""}, "offset": {"type": "integer", "description": "", "default": 0}, "limit": {"type": "integer", "description": "", "default": null}, "max_chars": {"type": "integer", "description": "", "default": 500000}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": ""}, "offset": {"type": "integer", "description": "", "default": 0}, "limit": {"type": "integer", "description": "", "default": null}, "max_chars": {"type": "integer", "description": "", "default": 500000}}, "required": ["file_path"]}', 'string', NULL, '{"category": "filesystem", "order": 4, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 2, '2026-11-25 13:02:46.116352+00:00', 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034565+00:00', '2026-11-20 11:38:15.055187+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'read_file');

