SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 93) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 93 END, 'read_image', 'Read Image (OCR)', '用我：读图片（OCR / 多模态）。
    别用我：文本或多格式文档用 read_file / read_any_file。
Read an image file: return its dimensions/format plus OCR-extracted text.

    Use when the user references or attaches an image (screenshot, scan,
    diagram, chart) and you need its text content. OCR runs through the
    system tesseract binary when available; otherwise the image metadata is
    returned so the model knows what was referenced.

    Args:
        file_path: Path to the image file (PNG/JPEG/WebP/GIF)', 'python_function', 'custom', '{"function_name": "read_image", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef read_image(file_path: str) -> str:\n    \"\"\"\n    用我：读图片（OCR / 多模态）。\n    别用我：文本或多格式文档用 read_file / read_any_file。\nRead an image file: return its dimensions/format plus OCR-extracted text.\n\n    Use when the user references or attaches an image (screenshot, scan,\n    diagram, chart) and you need its text content. OCR runs through the\n    system tesseract binary when available; otherwise the image metadata is\n    returned so the model knows what was referenced.\n\n    Args:\n        file_path: Path to the image file (PNG/JPEG/WebP/GIF)\n    \"\"\"\n    resolved, error = _resolve_sandbox_path(file_path)\n    if error:\n        return error\n    if not resolved.exists():\n        return f\"Error: file ''{file_path}'' not found\"\n    try:\n        from PIL import Image\n        with Image.open(resolved) as img:\n            fmt = img.format or \"unknown\"\n            dims = f\"{img.width}x{img.height}\"\n    except Exception as e:\n        return f\"Error: ''{file_path}'' is not a readable image: {e}\"\n    header = f\"Image: {resolved.name} ({fmt}, {dims})\"\n    import shutil\n    import subprocess\n    if shutil.which(\"tesseract\") is None:\n        return f\"{header}\\n(no OCR available — tesseract binary not installed)\"\n    try:\n        proc = subprocess.run(\n            [\"tesseract\", str(resolved), \"stdout\"],\n            # errors=\"replace\": tesseract''s stderr can carry non-UTF-8 bytes and\n            # text=True would then raise instead of returning the OCR text\n            capture_output=True, text=True, errors=\"replace\", timeout=60,\n        )\n        text = (proc.stdout or \"\").strip()\n    except Exception as e:\n        return f\"{header}\\n(OCR failed: {e})\"\n    if not text:\n        return f\"{header}\\n(no text detected in image)\"\n    return f\"{header}\\n{text}\"", "args_schema": {"file_path": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": ""}}, "required": ["file_path"]}', 'string', NULL, '{"category": "filesystem", "order": 5, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-15 08:05:00.528020+00:00', '2026-11-11 02:00:59.928169+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'read_image');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 51) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 51 END, 'reasoning_chain', 'Reasoning Chain', 'Break down a complex task into logical reasoning steps.

Replaces the MCP sequential-thinking server with native Python logic.

Args:
    task: The task or problem to reason about
    steps: Number of reasoning steps to perform (default: 5)

Returns:
    Structured reasoning breakdown

Example:
    >>> reasoning_chain("Plan a marketing strategy for a new product", 5)', 'python_function', 'custom', '{"function_name": "reasoning_chain", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef reasoning_chain(task: str, steps: int = 5) -> str:\n    \"\"\"\n    Break down a complex task into logical reasoning steps.\n\n    Replaces the MCP sequential-thinking server with native Python logic.\n\n    Args:\n        task: The task or problem to reason about\n        steps: Number of reasoning steps to perform (default: 5)\n\n    Returns:\n        Structured reasoning breakdown\n\n    Example:\n        >>> reasoning_chain(\"Plan a marketing strategy for a new product\", 5)\n    \"\"\"\n    logger.info(f\"Reasoning chain for task: {task}\")\n\n    # This is a simplified version. The actual LLM will do the reasoning.\n    # This tool just provides a structure for the agent to follow. The\n    # requested number of steps is honored (clamped to [1, 10]).\n\n    step_labels = [\n        \"Analyze the requirements and constraints\",\n        \"Identify key objectives and success criteria\",\n        \"Consider potential approaches and trade-offs\",\n        \"Evaluate risks and mitigation strategies\",\n        \"Synthesize into a concrete action plan\",\n    ]\n    try:\n        n = max(1, min(int(steps), 10))\n    except (TypeError, ValueError):\n        n = 5\n    step_lines = \"\\n\".join(\n        f\"{i}. {step_labels[i - 1] if i <= len(step_labels) else f''Deepen the analysis (step {i})''}\"\n        for i in range(1, n + 1)\n    )\n\n    reasoning_template = f\"\"\"\nTASK: {task}\n\nREASONING STEPS:\n{step_lines}\n\nNote: This is a reasoning framework. The agent should fill in the actual analysis.\n\"\"\"\n\n    return reasoning_template\n\ndef task(\n    description: str,\n    subagent_type: str = \"general\",\n    context: str = \"\",\n    expected_output: str = \"\"\n) -> str:\n    \"\"\"\n    Delegate a task to a specialized subagent for execution.\n\n    Use this tool to spawn work to configured subagents. The subagent will\n    execute the task and return the result. This enables parallel processing\n    and specialization.\n\n    Args:\n        description: Clear description of the task to perform\n        subagent_type: Type of subagent to use (e.g., \"research\", \"code\", \"writer\", \"general\")\n        context: Additional context or information for the subagent\n        expected_output: Description of expected output format/content\n\n    Returns:\n        Result from the subagent execution\n\n    Example:\n        >>> task(\n        ...     description=\"Research the latest trends in AI image generation\",\n        ...     subagent_type=\"research\",\n        ...     context=\"Focus on diffusion models released in 2024\",\n        ...     expected_output=\"A summary with key findings and links\"\n        ... )\n    \"\"\"\n    logger.info(f\"[TASK DELEGATION] Spawning subagent task: {description[:100]}...\")\n    logger.info(f\"  subagent_type: {subagent_type}\")\n    logger.info(f\"  context: {context[:100] if context else ''None''}...\")\n\n    # This is a placeholder - actual subagent execution is handled by the DeepAgents framework\n    # The framework intercepts this tool call and routes it to the appropriate subagent\n    # based on the subagent configurations in the DeepAgentConfig\n\n    # For now, return a message indicating the tool was called\n    # The actual implementation is in the DeepAgents middleware\n    return f\"\"\"[SUBAGENT TASK QUEUED]\nTask: {description}\nType: {subagent_type}\nContext: {context if context else ''None''}\nExpected Output: {expected_output if expected_output else ''Any relevant output''}\n\nNote: This task has been queued for subagent execution. The DeepAgents framework\nwill route this to the appropriate configured subagent. If no subagents are\nconfigured, this task will be executed by the main agent.\"\"\"", "args_schema": {"task": {"type": "string", "description": ""}, "steps": {"type": "integer", "description": "", "default": 5}}}', '{"type": "object", "properties": {"task": {"type": "string", "description": ""}, "steps": {"type": "integer", "description": "", "default": 5}}, "required": ["task"]}', 'string', NULL, '{"category": "reasoning", "order": 14, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'reasoning', TRUE, NULL, '["builtin", "reasoning"]', '2026-08-01 14:44:18.034575+00:00', '2026-10-13 09:07:27.335156+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'reasoning_chain');

