SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 78) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 78 END, 'save_analysis_result', 'Save Analysis Result', 'Save analysis results and optionally copy an attached file (e.g. a plot) to the output directory.

Args:
    text: Text content of the analysis report
    file_path: Optional path of a file attachment in the sandbox', 'python_function', 'custom', '{"function_name": "save_analysis_result", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef save_analysis_result(text: str, file_path: str | None = None) -> str:\n    \"\"\"Save analysis results and optionally copy an attached file (e.g. a plot) to the output directory.\n\n    Args:\n        text: Text content of the analysis report\n        file_path: Optional path of a file attachment in the sandbox\n    \"\"\"\n    output_dir = Path(\"./_analysis_output\")\n    output_dir.mkdir(parents=True, exist_ok=True)\n    report_path = output_dir / \"analysis_report.txt\"\n    report_path.write_text(text)\n    if file_path:\n        # Only copy attachments that live inside the workspace sandbox.\n        fp, err = _resolve_sandbox_path(file_path)\n        if err:\n            return f\"Error saving analysis result: {err}\"\n        if fp.exists():\n            local_path = output_dir / fp.name\n            local_path.write_bytes(fp.read_bytes())\n    return f\"Analysis results saved to {output_dir.resolve()}.\"", "args_schema": {"text": {"type": "string", "description": ""}, "file_path": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"text": {"type": "string", "description": ""}, "file_path": {"type": "string", "description": "", "default": null}}, "required": ["text"]}', 'string', NULL, '{"category": "analysis", "order": 18, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'data_analysis', TRUE, NULL, '["builtin", "data_analysis"]', '2026-08-01 14:44:18.034627+00:00', '2026-11-25 17:22:15.346196+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'save_analysis_result');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 84) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 84 END, 'search_skills', 'Search Skills (empty query = list all)', '用我：按名字 / 描述 / tags 找技能；**query 留空就是列出全部**（按使用次数排序，最多 50 条）。', 'python_function', 'custom', '{"function_name": "search_skills", "code": "def _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef search_skills(query: str = \"\") -> str:\n    \"\"\"\n    用我：按名字 / 描述 / tags 找技能；**query 留空就是列出全部**（按使用次数排序，最多 50 条）。\n    别用我：要知道某个技能怎么用，读它的 SKILL.md，不要靠这里的摘要猜。\n\n    Search skills by name, description, or tags — with an EMPTY query, list every skill (most\n    used first). Listing and searching are the same question about the same table, which is why the\n    old pair (`pg_list_skills` + `search_skills`) is one tool now.\n\n    Args:\n        query: Search keyword (e.g., ''stock'', ''database'', ''research''). Empty lists all skills.\n\n    Returns:\n        Formatted list of matching skills\n\n    Example:\n        >>> search_skills(\"stock market\")\n    \"\"\"\n    from models.skill import Skill\n    db = _get_pg_session()\n    try:\n        query_lower = (query or \"\").strip().lower()\n        skills = db.query(Skill).order_by(Skill.usage_count.desc()).all()\n        if not query_lower:\n            # listing: no filter, capped the way pg_list_skills used to cap it\n            skills = skills[:50]\n            lines = [f\"## Skills ({len(skills)} shown, most used first)\", \"\"]\n            for s_ in skills:\n                lines.append(f\"### {s_.name} (`{s_.skill_id}`)\")\n                lines.append(f\"  Description: {s_.description or ''N/A''}\")\n                lines.append(f\"  Tags: {'', ''.join(s_.tags or [])}\")\n                lines.append(f\"  Used: {s_.usage_count}x\")\n                lines.append(\"\")\n            return \"\\n\".join(lines)\n        matches = []\n        for s in skills:\n            if (query_lower in s.name.lower() or\n                query_lower in (s.description or \"\").lower() or\n                any(query_lower in t.lower() for t in (s.tags or [])) or\n                any(query_lower in t.lower() for t in (s.triggers or []))):\n                matches.append(s)\n        if not matches:\n            return f\"No skills found matching ''{query}''.\"\n        lines = [f\"## Matching skills for ''{query}'' ({len(matches)} found)\", \"\"]\n        for s in matches:\n            tags = \", \".join(s.tags or [])\n            triggers = \"; \".join((s.triggers or [])[:3])\n            lines.append(f\"### {s.name} (`{s.skill_id}`)\")\n            lines.append(f\"  Description: {s.description or ''N/A''}\")\n            lines.append(f\"  Tags: {tags}\")\n            lines.append(f\"  Triggers: {triggers}\")\n            lines.append(f\"  Used: {s.usage_count}x\")\n            lines.append(\"\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error searching skills: {e}\"\n    finally:\n        db.close()", "args_schema": {"query": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"query": {"type": "string", "description": "", "default": ""}}, "required": []}', 'string', NULL, '{"category": "platform", "order": 35, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'platform', TRUE, NULL, '["builtin", "platform"]', '2026-08-01 14:44:18.034639+00:00', '2026-11-25 17:22:15.346198+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'search_skills');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 94) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 94 END, 'skill', 'Read Skill', 'Fetch a skill''s full instructions by its id — or one of its support files.', 'python_function', 'custom', '{"function_name": "skill", "code": "# --- imports ---\n\nfrom pathlib import Path\n\ndef _skill_support_files(base: Path, limit: int = 40) -> list:\n    \"\"\"Files next to SKILL.md, as skill-relative paths (sorted, capped).\n\n    A skill that ships templates or reference tables is useless if the model\n    cannot see that they exist: the instructions are in the DB, the files are on\n    disk. Seen 2026-11-01 — Agent Builder rebuilt a template from memory because\n    `templates/` was invisible.\n    \"\"\"\n    if base is None or not base.is_dir():\n        return []\n    out = []\n    for path in sorted(base.rglob(\"*\")):\n        if not path.is_file() or path.name == \"SKILL.md\":\n            continue\n        out.append(str(path.relative_to(base)))\n        if len(out) >= limit:\n            break\n    return out\n\nasync def skill(skill_id: str, file: str = \"\", lang: str = \"\") -> str:\n    \"\"\"Fetch a skill''s full instructions by its id — or one of its support files.\n\n    Use when the user asks about a topic that a skill covers but the skill was\n    not pre-injected into your context. Reads the skill from the library on\n    demand (progressive disclosure).\n\n    Skills may ship supporting files next to SKILL.md (templates, fact tables,\n    scripts). Those are NOT loaded with the instructions; list them with this\n    tool first (it prints `Support files:`), then ask for one by path.\n\n    Args:\n        skill_id: The skill''s id (e.g. \"web-search\", \"text-summarizer\")\n        file: Optional path inside the skill directory, e.g.\n              \"templates/T2-supervisor-experts.md\". Leave empty for the\n              instructions. Must stay inside the skill.\n        lang: Which language to serve. Empty (the default) serves `SKILL.md` — the working text, which is\n              Chinese for every skill that has been translated. `lang=\"en\"` serves the archived English\n              original from `backend/skills/en-originals/<id>/SKILL.md`, which nothing else reads: it is a\n              backup and a source for checking a translation, and it enters a context only when asked for\n              by name.\n    \"\"\"\n    try:\n        from core.skills.registry import get_skill_registry\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        found = registry.get_skill(skill_id)\n        if found is None:\n            registry.record_usage(skill_id, \"explicit\", \"failed\", source=\"skill tool: not found\")\n            available = \", \".join(sorted(s.skill_id for s in registry.list_all())) or \"none\"\n            return f\"Error: skill ''{skill_id}'' not found. Available skills: {available}\"\n        base = Path(found.source_path) if getattr(found, \"source_path\", None) else None\n\n        if file:\n            if base is None or not base.is_dir():\n                return f\"Error: skill ''{skill_id}'' has no source directory on disk.\"\n            target = (base / file).resolve()\n            try:\n                target.relative_to(base.resolve())\n            except ValueError:\n                return f\"Error: ''{file}'' escapes skill ''{skill_id}''.\"\n            if not target.is_file():\n                listing = _skill_support_files(base)\n                return (f\"Error: ''{file}'' not found in skill ''{skill_id}''. \"\n                        f\"Support files: {'', ''.join(listing) or ''none''}\")\n            text = target.read_text(encoding=\"utf-8\", errors=\"replace\")\n            return f\"# Skill file: {skill_id}/{file}\\n\\n{text}\"\n\n        # The working text is Chinese: `SKILL.md` is what an agent reads, and the English original lives\n        # outside the skill library (`backend/skills/en-originals/<id>/`) as a backup. Nothing loads it\n        # unless the caller asks for it explicitly by language — which is why the default below is the\n        # canonical file and not a sibling.\n        body_text, body_lang = found.instructions, \"zh\"\n        if lang and lang.split(\"-\")[0].lower() == \"en\":\n            # base is .../skills/builtin/<id>; the archive sits beside the library root\n            archived = (Path(base).parents[1] / \"en-originals\" / found.skill_id / \"SKILL.md\"\n                        if base is not None else None)\n            if archived is not None and archived.is_file():\n                raw = archived.read_text(encoding=\"utf-8\", errors=\"replace\")\n                if raw.startswith(\"---\"):\n                    end = raw.find(\"\\n---\", 3)\n                    if end != -1:\n                        raw = raw[end + 4:].lstrip(\"\\n\")\n                body_text, body_lang = raw, \"en\"\n        parts = [\n            f\"# Skill: {found.name}\" + (f\"  (instructions: {body_lang})\" if body_lang != \"zh\" else \"\"),\n            f\"**Description:** {found.description}\",\n            \"\",\n            body_text,\n        ]\n        if found.examples:\n            parts += [\"\", \"**Examples:**\", found.examples]\n        if found.allowed_tools:\n            parts += [\"\", f\"**Allowed tools:** {'', ''.join(found.allowed_tools)}\"]\n        support = _skill_support_files(base) if base else []\n        if support:\n            parts += [\n                \"\",\n                \"**Support files** (not loaded above — fetch one with \"\n                f\"skill(\\\"{found.skill_id}\\\", file=\\\"<path>\\\")):\",\n                *[f\"- {f}\" for f in support],\n            ]\n        # Count the use. Until this existed, `usage_count`/`avg_success_rate` were read by the UI and written by\n        # nobody: the library showed \"0 uses\" for skills that had been served hundreds of times.\n        registry.record_usage(found.skill_id, \"explicit\", \"success\", source=\"skill tool\")\n        return \"\\n\".join(parts)\n    except Exception as e:\n        return f\"Error loading skill ''{skill_id}'': {e}\"", "args_schema": {"skill_id": {"type": "string", "description": ""}, "file": {"type": "string", "description": "", "default": ""}, "lang": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"skill_id": {"type": "string", "description": ""}, "file": {"type": "string", "description": "", "default": ""}, "lang": {"type": "string", "description": "", "default": ""}}, "required": ["skill_id"]}', 'string', NULL, '{"category": "skills", "order": 27, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 5, '2026-11-25 13:02:34.365852+00:00', 0, NULL, '1.0.0', NULL, 'skills', TRUE, NULL, '["builtin", "skills"]', '2026-08-15 08:09:02.162849+00:00', '2026-11-25 17:22:15.346199+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'skill');

