SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 255) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 255 END, 'talent_verify_jd_report', 'Talent - Verify JD Report (交付前回检)', '用我：招聘流水线里"交付前回检"这一步 —— 把一份 JD 的事实**现场重算**,和你要写进报告的数字对账。

返回一张「主张 → 实测 → 结论」的表:原文行数、客户/HR 引用条数、每条 verbatim 是否逐字在原文里、
txt_line 是否真实行号、excluded 条目、门禁汇总行(现场跑一遍)。

为什么需要它:agent 交过一份报告,真话和假话同时存在 —— 门禁 161 checks 全绿(真),
但「原文 7 行」(实际 48)、「有一行含『主导内审』」(这份 JD 没有)、「excluded 是抬头标题」
(实际是 IATF16949)三句都是假的。它们有同一个来源:**从记忆里写**,而记忆来自另一份 JD。
所以这一步不许凭记忆:每个数字现场重算。

别用我:起草/修改 JD 本身(那是脚本 + edit_file 的事);这里只读不写。

Args:
    jd: JD 名,等于 work/talent/jd_links/<jd>.yaml 的文件名主干,例如 "品质经理"

Returns:
    回检表。**最后一行"全部对得上。可以交付。"才表示通过**;
    出现「不一致」就说明报告里有数字/句子对不上,必须先改报告。', 'python_function', 'custom', '{"function_name": "talent_verify_jd_report", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport sys as _sys\n\ndef talent_verify_jd_report(jd: str) -> str:\n    \"\"\"用我：招聘流水线里\"交付前回检\"这一步 —— 把一份 JD 的事实**现场重算**,和你要写进报告的数字对账。\n\n    返回一张「主张 → 实测 → 结论」的表:原文行数、客户/HR 引用条数、每条 verbatim 是否逐字在原文里、\n    txt_line 是否真实行号、excluded 条目、门禁汇总行(现场跑一遍)。\n\n    为什么需要它:agent 交过一份报告,真话和假话同时存在 —— 门禁 161 checks 全绿(真),\n    但「原文 7 行」(实际 48)、「有一行含『主导内审』」(这份 JD 没有)、「excluded 是抬头标题」\n    (实际是 IATF16949)三句都是假的。它们有同一个来源:**从记忆里写**,而记忆来自另一份 JD。\n    所以这一步不许凭记忆:每个数字现场重算。\n\n    别用我:起草/修改 JD 本身(那是脚本 + edit_file 的事);这里只读不写。\n\n    Args:\n        jd: JD 名,等于 work/talent/jd_links/<jd>.yaml 的文件名主干,例如 \"品质经理\"\n\n    Returns:\n        回检表。**最后一行\"全部对得上。可以交付。\"才表示通过**;\n        出现「不一致」就说明报告里有数字/句子对不上,必须先改报告。\n    \"\"\"\n    try:\n        import sys as _sys\n        from pathlib import Path as _Path\n        _backend = _Path(__file__).resolve().parents[1]\n        if str(_backend) not in _sys.path:\n            _sys.path.insert(0, str(_backend))\n        from scripts.talent.verify_jd_report import collect, render\n\n        result = collect(jd)\n        text = render(result)\n        verdict = \"PASS\" if result.get(\"ok\") else \"FAIL\"\n        return f\"{text}\\n\\n[{verdict}] talent_verify_jd_report(jd={jd!r})\"\n    except Exception as exc:                       # 回检自己崩了也必须说清楚,不许静默\n        return (f\"Error: 回检没能跑完（{type(exc).__name__}: {exc}）。\"\n                f\"**这不等于通过** —— 回检崩了按红处理。\")", "args_schema": {"jd": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"jd": {"type": "string", "description": ""}}, "required": ["jd"]}', 'string', NULL, '{"category": "database", "order": 59, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-11-20 11:38:15.066578+00:00', '2026-11-25 17:22:15.346210+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'talent_verify_jd_report');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 52) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 52 END, 'task', 'Task (Subagent)', 'Delegate a task to a specialized subagent for execution.

Use this tool to spawn work to configured subagents. The subagent will
execute the task and return the result. This enables parallel processing
and specialization.

Args:
    description: Clear description of the task to perform
    subagent_type: Type of subagent to use (e.g., "research", "code", "writer", "general")
    context: Additional context or information for the subagent
    expected_output: Description of expected output format/content

Returns:
    Result from the subagent execution

Example:
    >>> task(
    ...     description="Research the latest trends in AI image generation",
    ...     subagent_type="research",
    ...     context="Focus on diffusion models released in 2024",
    ...     expected_output="A summary with key findings and links"
    ... )', 'python_function', 'custom', '{"function_name": "task", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef task(\n    description: str,\n    subagent_type: str = \"general\",\n    context: str = \"\",\n    expected_output: str = \"\"\n) -> str:\n    \"\"\"\n    Delegate a task to a specialized subagent for execution.\n\n    Use this tool to spawn work to configured subagents. The subagent will\n    execute the task and return the result. This enables parallel processing\n    and specialization.\n\n    Args:\n        description: Clear description of the task to perform\n        subagent_type: Type of subagent to use (e.g., \"research\", \"code\", \"writer\", \"general\")\n        context: Additional context or information for the subagent\n        expected_output: Description of expected output format/content\n\n    Returns:\n        Result from the subagent execution\n\n    Example:\n        >>> task(\n        ...     description=\"Research the latest trends in AI image generation\",\n        ...     subagent_type=\"research\",\n        ...     context=\"Focus on diffusion models released in 2024\",\n        ...     expected_output=\"A summary with key findings and links\"\n        ... )\n    \"\"\"\n    logger.info(f\"[TASK DELEGATION] Spawning subagent task: {description[:100]}...\")\n    logger.info(f\"  subagent_type: {subagent_type}\")\n    logger.info(f\"  context: {context[:100] if context else ''None''}...\")\n\n    # This is a placeholder - actual subagent execution is handled by the DeepAgents framework\n    # The framework intercepts this tool call and routes it to the appropriate subagent\n    # based on the subagent configurations in the DeepAgentConfig\n\n    # For now, return a message indicating the tool was called\n    # The actual implementation is in the DeepAgents middleware\n    return f\"\"\"[SUBAGENT TASK QUEUED]\nTask: {description}\nType: {subagent_type}\nContext: {context if context else ''None''}\nExpected Output: {expected_output if expected_output else ''Any relevant output''}\n\nNote: This task has been queued for subagent execution. The DeepAgents framework\nwill route this to the appropriate configured subagent. If no subagents are\nconfigured, this task will be executed by the main agent.\"\"\"", "args_schema": {"description": {"type": "string", "description": ""}, "subagent_type": {"type": "string", "description": "", "default": "general"}, "context": {"type": "string", "description": "", "default": ""}, "expected_output": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"description": {"type": "string", "description": ""}, "subagent_type": {"type": "string", "description": "", "default": "general"}, "context": {"type": "string", "description": "", "default": ""}, "expected_output": {"type": "string", "description": "", "default": ""}}, "required": ["description"]}', 'string', NULL, '{"category": "agents", "order": 15, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'delegation', TRUE, NULL, '["builtin", "delegation"]', '2026-08-01 14:44:18.034577+00:00', '2026-10-13 09:07:27.335157+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'task');

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at, is_deprecated, superseded_by, deprecated_reason)
SELECT CASE WHEN EXISTS (SELECT 1 FROM custom_tools WHERE id = 44) THEN nextval(pg_get_serial_sequence('custom_tools', 'id')) ELSE 44 END, 'tavily_search', 'Tavily Search', 'Search the web using Tavily - an AI-optimized search engine.

Returns structured, summarized results perfect for AI consumption.
Requires TAVILY_API_KEY configured in Settings > API Keys.

Use this for more accurate, context-aware search results compared
to general web search. Especially good for research questions.

Args:
    query: The search query
    max_results: Maximum number of results to return (default: 5)

Returns:
    Search results as formatted text

Example:
    >>> await tavily_search("LangGraph v1.0 middleware system")
    >>> await tavily_search("Python async patterns", max_results=3)', 'python_function', 'custom', '{"function_name": "tavily_search", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\n# --- tavily guard ---\n\ntry:\n    from langchain_community.tools.tavily_search import TavilySearchResults\n    TAVILY_AVAILABLE = True\nexcept ImportError:\n    TAVILY_AVAILABLE = False\n\nasync def tavily_search(query: str, max_results: int = 5) -> str:\n    \"\"\"\n    Search the web using Tavily - an AI-optimized search engine.\n\n    Returns structured, summarized results perfect for AI consumption.\n    Requires TAVILY_API_KEY configured in Settings > API Keys.\n\n    Use this for more accurate, context-aware search results compared\n    to general web search. Especially good for research questions.\n\n    Args:\n        query: The search query\n        max_results: Maximum number of results to return (default: 5)\n\n    Returns:\n        Search results as formatted text\n\n    Example:\n        >>> await tavily_search(\"LangGraph v1.0 middleware system\")\n        >>> await tavily_search(\"Python async patterns\", max_results=3)\n    \"\"\"\n    try:\n        from config import get_api_key_from_db\n\n        api_key = get_api_key_from_db(\"tavily_api_key\")\n        if not api_key:\n            return (\n                \"Tavily API key not configured.\\n\\n\"\n                \"To use Tavily search:\\n\"\n                \"1. Go to Settings > API Keys\\n\"\n                \"2. Add your TAVILY_API_KEY\\n\"\n                \"3. Alternatively, use web_search (DuckDuckGo, free, no key required)\"\n            )\n\n        if not TAVILY_AVAILABLE:\n            # langchain_community is always present in LangConfig; the flag\n            # guards environments where it is missing. We call Tavily''s REST\n            # API directly below (no wrapper dependency), so this is only a\n            # soft guard.\n            pass\n\n        logger.info(f\"Tavily search: {query}\")\n\n        # Call the Tavily REST API directly — the langchain wrapper''s\n        # parameter names keep changing across versions (api_key vs\n        # tavily_api_key) and it wants an env var in some versions. Direct\n        # HTTP is stable and returns the same structured content.\n        import httpx as _httpx\n\n        async with _httpx.AsyncClient(timeout=15) as client:\n            r = await client.post(\n                \"https://api.tavily.com/search\",\n                json={\n                    \"api_key\": api_key,\n                    \"query\": query,\n                    \"max_results\": max_results,\n                    \"include_answer\": False,\n                },\n            )\n            r.raise_for_status()\n            data = r.json()\n\n        results = data.get(\"results\") or []\n        if not results:\n            return f\"No results found for: {query}\"\n\n        result_text = f\"Search results for ''{query}'' (via Tavily):\\n\\n\"\n        for i, r_item in enumerate(results, 1):\n            content = r_item.get(\"content\", \"\")\n            url = r_item.get(\"url\", \"\")\n            if url:\n                result_text += f\"{i}. {content}\\n   Source: {url}\\n\\n\"\n            else:\n                result_text += f\"{i}. {content}\\n\\n\"\n\n        logger.info(f\"Tavily search returned {len(results)} results for: {query}\")\n        return result_text\n\n    except Exception as e:\n        logger.error(f\"Tavily search failed: {e}\")\n        return f\"Tavily search error: {str(e)}\"", "args_schema": {"query": {"type": "string", "description": ""}, "max_results": {"type": "integer", "description": "", "default": 5}}}', '{"type": "object", "properties": {"query": {"type": "string", "description": ""}, "max_results": {"type": "integer", "description": "", "default": 5}}, "required": ["query"]}', 'string', NULL, '{"category": "web", "order": 1, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {"requires_api_key": "TAVILY_API_KEY"}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'web', TRUE, 'TAVILY_API_KEY', '["builtin", "web"]', '2026-08-01 14:44:18.034560+00:00', '2026-08-22 15:18:58.895640+00:00', FALSE, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'tavily_search');

